package com.agamemnon.companion;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Starts a RuneLite client with this plugin loaded, for testing in the actual
 * game. Lives in the test source set so it never ships in the plugin jar.
 *
 * Point it at a local API with:
 *   -Dagamemnon.baseUrl=http://localhost:3000/api/v1
 *
 * Only a human logging in validates this end to end. Do not automate the game
 * client — that breaks Jagex's rules.
 */
public class AgamemnonCompanionLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AgamemnonCompanionPlugin.class);
		RuneLite.main(args);
	}
}

package com.agamemnon.companion;

import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Checks the generated table against the constants it was generated from, so a
 * stale table or a bad rename is caught rather than shipped.
 */
public class AchievementVarbitsTest
{
	private static int idOf(Class<?> holder, String name) throws Exception
	{
		Field field = holder.getDeclaredField(name);
		field.setAccessible(true);
		return field.getInt(null);
	}

	@Test
	public void everyCombatTaskPointsAtTheVarbitItWasNamedFor() throws Exception
	{
		Class<?> varbits = Class.forName("net.runelite.api.gameval.VarbitID");

		for (AchievementVarbits.Entry entry : AchievementVarbits.COMBAT_TASKS)
		{
			// Only the shared prefix was stripped, so this reverses exactly.
			assertEquals(entry.name, idOf(varbits, "CA_TASK_" + entry.name), entry.id);
		}
	}

	/**
	 * CA_TASK_ is shared with the interface's own settings. Reporting
	 * CA_TASK_FILTER_COMPLETED — which filter the player picked in the UI — as
	 * a completed achievement would be a plain lie about their account.
	 */
	@Test
	public void interfaceSettingsAreNotReportedAsAchievements()
	{
		for (AchievementVarbits.Entry entry : AchievementVarbits.COMBAT_TASKS)
		{
			assertTrue(
				"interface setting leaked into the task table: " + entry.name,
				!entry.name.startsWith("FILTER_")
					&& !entry.name.equals("POPUP")
					&& !entry.name.equals("RECOMPLETION_NOTIFICATIONS"));
		}
	}

	@Test
	public void everyDiaryTierPointsAtTheVarbitItWasNamedFor() throws Exception
	{
		Class<?> varbits = Class.forName("net.runelite.api.gameval.VarbitID");

		for (AchievementVarbits.Entry entry : AchievementVarbits.DIARY_TIERS)
		{
			// ARDOUGNE_EASY came from ARDOUGNE_DIARY_EASY_COMPLETE.
			int split = entry.name.lastIndexOf('_');
			String original = entry.name.substring(0, split) + "_DIARY_"
				+ entry.name.substring(split + 1) + "_COMPLETE";
			assertEquals(entry.name, idOf(varbits, original), entry.id);
		}
	}

	@Test
	public void everyDiaryVarpPointsAtTheVarpItWasNamedFor() throws Exception
	{
		Class<?> varps = Class.forName("net.runelite.api.gameval.VarPlayerID");

		for (AchievementVarbits.Entry entry : AchievementVarbits.DIARY_VARPS)
		{
			assertEquals(entry.name, idOf(varps, entry.name), entry.id);
		}
	}

	@Test
	public void theTableIsTheExpectedSize()
	{
		// Guards against an extraction that silently produced nothing.
		assertEquals(471, AchievementVarbits.COMBAT_TASKS.length);
		assertEquals(77, AchievementVarbits.COMBAT_TOTALS.length);
		assertEquals(45, AchievementVarbits.DIARY_TIERS.length);
		assertEquals(10, AchievementVarbits.DIARY_VARPS.length);
		assertEquals(4, AchievementVarbits.QUEST_COUNTS.length);
		assertEquals(Quest.values().length, AchievementVarbits.QUEST_KINDS.length);
	}

	@Test
	public void namesAreUniqueWithinEachTable()
	{
		for (AchievementVarbits.Entry[] table : new AchievementVarbits.Entry[][]{
			AchievementVarbits.COMBAT_TASKS,
			AchievementVarbits.COMBAT_TOTALS,
			AchievementVarbits.DIARY_TIERS,
			AchievementVarbits.DIARY_VARPS,
			AchievementVarbits.QUEST_COUNTS,
		})
		{
			Set<String> names = new HashSet<>();
			for (AchievementVarbits.Entry entry : table)
			{
				assertTrue("duplicate " + entry.name, names.add(entry.name));
			}
		}

		Set<String> kinds = new HashSet<>();
		for (AchievementVarbits.KindEntry entry : AchievementVarbits.QUEST_KINDS)
		{
			assertTrue("duplicate " + entry.name, kinds.add(entry.name));
		}
	}

	@Test
	public void diaryTiersCoverTheFourDifficulties()
	{
		Set<String> tiers = new HashSet<>();
		for (AchievementVarbits.Entry entry : AchievementVarbits.DIARY_TIERS)
		{
			tiers.add(entry.name.substring(entry.name.lastIndexOf('_') + 1));
		}

		assertEquals(new HashSet<>(java.util.Arrays.asList(
			"EASY", "MEDIUM", "HARD", "ELITE")), tiers);
	}

	/**
	 * The game keeps its own tally, and it disagrees with counting the enum:
	 * RuneLite's Quest values mix miniquests in and the game does not count
	 * those, so a hand count reads high.
	 */
	@Test
	public void questCountsComeFromTheGameItself() throws Exception
	{
		Class<?> varbits = Class.forName("net.runelite.api.gameval.VarbitID");
		for (AchievementVarbits.Entry entry : AchievementVarbits.QUEST_COUNTS)
		{
			assertEquals(entry.name, idOf(varbits, entry.name), entry.id);
		}
	}

	@Test
	public void questStatesComeFromTheApiRatherThanATable()
	{
		// Quest.getState(client) answers directly, so states are not tabulated.
		assertTrue(Quest.values().length > 200);
	}

	/**
	 * Kinds come from DBTableID.Quest.Row prefixes (QUEST_ / MINIQUEST_ /
	 * SUBQUEST_), joined to the Quest enum by id. That join is what lets the
	 * dashboard's Done chip agree with the game's quest tally instead of
	 * counting miniquests as quests.
	 */
	@Test
	public void everyQuestKindMatchesTheDbRowPrefix() throws Exception
	{
		Class<?> rowClass = Class.forName("net.runelite.api.gameval.DBTableID$Quest$Row");
		Map<Integer, String> kindById = new HashMap<>();
		for (Field field : rowClass.getDeclaredFields())
		{
			if (field.getType() != int.class)
			{
				continue;
			}
			field.setAccessible(true);
			String name = field.getName();
			String kind = name.substring(0, name.indexOf('_'));
			kindById.put(field.getInt(null), kind);
		}

		Map<String, String> kindByName = new HashMap<>();
		for (AchievementVarbits.KindEntry entry : AchievementVarbits.QUEST_KINDS)
		{
			kindByName.put(entry.name, entry.kind);
		}

		for (Quest quest : Quest.values())
		{
			String expected = kindById.get(quest.getId());
			assertNotNull("no DB row for " + quest.name(), expected);
			assertEquals(quest.name(), expected, kindByName.get(quest.name()));
		}
	}
}

package com.agamemnon.companion;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The plugin serialises with the Gson instance RuneLite injects; a plain one is
 * equivalent for checking the shape of the JSON.
 */
public class XpSyncPayloadTest
{
	private static final Gson GSON = new Gson();

	private static JsonObject serialise(XpSyncPayload payload)
	{
		// The instance method, not JsonParser.parseString: RuneLite ships Gson
		// 2.8.5 and the static overload only arrived in 2.8.6.
		return new JsonParser().parse(GSON.toJson(payload)).getAsJsonObject();
	}

	private static XpSyncPayload payload(long accountHash, Map<String, Integer> skills)
	{
		return new XpSyncPayload(
			accountHash,
			"3f2504e0-4f89-11d3-9a0c-0305e82c3301",
			"Zezinho",
			"NORMAL",
			"MEMBERS",
			1_756_100_000_000L,
			false,
			skills,
			128_500_000L);
	}

	@Test
	public void sendsAccountHashAsAStringNotANumber()
	{
		JsonObject json = serialise(payload(1234567890123456789L, Collections.emptyMap()));

		// A JSON number would be parsed as a double by any JavaScript consumer
		// and silently lose precision past 2^53.
		assertTrue(json.get("accountHash").getAsJsonPrimitive().isString());
		assertFalse(json.get("accountHash").getAsJsonPrimitive().isNumber());
	}

	@Test
	public void preservesTheFullSixtyFourBitHash()
	{
		long hash = 9223372036854775807L;
		JsonObject json = serialise(payload(hash, Collections.emptyMap()));

		assertEquals("9223372036854775807", json.get("accountHash").getAsString());
	}

	@Test
	public void carriesTheSchemaVersion()
	{
		JsonObject json = serialise(payload(1L, Collections.emptyMap()));
		assertEquals(XpSyncPayload.SCHEMA_VERSION, json.get("schemaVersion").getAsInt());
	}

	@Test
	public void carriesAbsoluteSkillValues()
	{
		Map<String, Integer> skills = new LinkedHashMap<>();
		skills.put("ATTACK", 4_300_000);
		skills.put("WOODCUTTING", 13_034_431);

		JsonObject json = serialise(payload(1L, skills));
		JsonObject serialisedSkills = json.getAsJsonObject("skills");

		assertEquals(4_300_000, serialisedSkills.get("ATTACK").getAsInt());
		assertEquals(13_034_431, serialisedSkills.get("WOODCUTTING").getAsInt());
	}

	@Test
	public void neverCarriesAnythingAboutOtherPlayers()
	{
		JsonObject json = serialise(payload(1L, Collections.emptyMap()));

		// The full field list is the wire contract. Anything new appearing here
		// is a deliberate decision, not an accident.
		assertEquals(
			"[accountHash, accountType, clientTimestamp, displayName, schemaVersion, "
				+ "sessionEnd, sessionId, skills, totalXp, worldType]",
			json.keySet().stream().sorted().collect(
				java.util.stream.Collectors.toList()).toString());
	}

	@Test
	public void toleratesNullSkills()
	{
		JsonObject json = serialise(payload(1L, null));
		assertEquals(0, json.getAsJsonObject("skills").size());
	}
}

package com.agamemnon.companion;

import java.util.Collections;
import java.util.EnumSet;
import net.runelite.api.WorldType;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AccountDetailsTest
{
	@Test
	public void flagsWorldsWithArtificialXp()
	{
		// Leagues reports as SEASONAL; there is no LEAGUE constant in WorldType.
		assertTrue(AccountDetails.isArtificialWorld(EnumSet.of(WorldType.SEASONAL)));
		assertTrue(AccountDetails.isArtificialWorld(EnumSet.of(WorldType.DEADMAN)));
		assertTrue(AccountDetails.isArtificialWorld(EnumSet.of(WorldType.BETA_WORLD)));
		assertTrue(AccountDetails.isArtificialWorld(EnumSet.of(WorldType.TOURNAMENT_WORLD)));
	}

	@Test
	public void flagsASetWhereOnlyOneMemberIsArtificial()
	{
		assertTrue(AccountDetails.isArtificialWorld(
			EnumSet.of(WorldType.MEMBERS, WorldType.SEASONAL)));
	}

	@Test
	public void leavesOrdinaryWorldsAlone()
	{
		assertFalse(AccountDetails.isArtificialWorld(EnumSet.of(WorldType.MEMBERS)));
		assertFalse(AccountDetails.isArtificialWorld(
			EnumSet.of(WorldType.MEMBERS, WorldType.HIGH_RISK, WorldType.PVP)));
		assertFalse(AccountDetails.isArtificialWorld(Collections.emptySet()));
		assertFalse(AccountDetails.isArtificialWorld(null));
	}

	@Test
	public void describesTheWholeWorldTypeSet()
	{
		// getWorldType() returns a set, so flattening to a single name would
		// throw information away.
		assertEquals("MEMBERS", AccountDetails.describeWorldTypes(
			EnumSet.of(WorldType.MEMBERS)));
		assertEquals("MEMBERS,SEASONAL", AccountDetails.describeWorldTypes(
			EnumSet.of(WorldType.MEMBERS, WorldType.SEASONAL)));
		assertEquals("", AccountDetails.describeWorldTypes(Collections.emptySet()));
		assertEquals("", AccountDetails.describeWorldTypes(null));
	}

	@Test
	public void namesTheKnownAccountTypes()
	{
		assertEquals("NORMAL", AccountDetails.describeAccountType(0));
		assertEquals("IRONMAN", AccountDetails.describeAccountType(1));
		assertEquals("ULTIMATE_IRONMAN", AccountDetails.describeAccountType(2));
		assertEquals("HARDCORE_IRONMAN", AccountDetails.describeAccountType(3));
		assertEquals("GROUP_IRONMAN", AccountDetails.describeAccountType(4));
		assertEquals("HARDCORE_GROUP_IRONMAN", AccountDetails.describeAccountType(5));
		assertEquals("UNRANKED_GROUP_IRONMAN", AccountDetails.describeAccountType(6));
	}

	@Test
	public void passesUnknownAccountTypesThroughInsteadOfGuessing()
	{
		// A value added by a future update should land in the data intact
		// rather than being mislabelled as NORMAL.
		assertEquals("UNKNOWN_7", AccountDetails.describeAccountType(7));
		assertEquals("UNKNOWN_-1", AccountDetails.describeAccountType(-1));
	}
}

package com.agamemnon.companion;

import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AgamemnonCompanionPluginTest
{
	/** Any positive value works; nothing here depends on it being a real one. */
	private static final long ACCOUNT = 1234567890123456789L;
	private static final String SESSION = "3f2504e0-4f89-11d3-9a0c-0305e82c3301";

	/**
	 * Regression: the shutdown flush used to be gated on there being unsent XP.
	 * Toggling the plugin off right after a clean sync therefore sent nothing,
	 * and the session was left open on the server forever.
	 */
	@Test
	public void closesTheSessionOnShutdownEvenWithNothingPending()
	{
		assertTrue(AgamemnonCompanionPlugin.shouldFlushOnShutdown(
			true, true, ACCOUNT, SESSION));
	}

	@Test
	public void sendsNothingOnShutdownWhenThereIsNoSessionToClose()
	{
		// Never logged in, so there is no session and no account to attribute
		// anything to.
		assertFalse(AgamemnonCompanionPlugin.shouldFlushOnShutdown(
			true, true, -1L, null));
		assertFalse(AgamemnonCompanionPlugin.shouldFlushOnShutdown(
			true, true, ACCOUNT, null));
		assertFalse(AgamemnonCompanionPlugin.shouldFlushOnShutdown(
			true, true, -1L, SESSION));
	}

	@Test
	public void sendsNothingOnShutdownWhenSyncingIsOff()
	{
		// The user never opted in; shutting down must not be a way to leak one
		// last payload.
		assertFalse(AgamemnonCompanionPlugin.shouldFlushOnShutdown(
			true, false, ACCOUNT, SESSION));
	}

	@Test
	public void sendsNothingOnShutdownWhenAlreadyInactive()
	{
		assertFalse(AgamemnonCompanionPlugin.shouldFlushOnShutdown(
			false, true, ACCOUNT, SESSION));
	}

	@Test
	public void firstFailureWaitsTheBaseDelay()
	{
		assertEquals(TimeUnit.SECONDS.toMillis(30), AgamemnonCompanionPlugin.backoffMillis(1));
	}

	@Test
	public void backoffGrowsWithConsecutiveFailures()
	{
		long previous = AgamemnonCompanionPlugin.backoffMillis(1);
		for (int failures = 2; failures <= 6; failures++)
		{
			long current = AgamemnonCompanionPlugin.backoffMillis(failures);
			assertTrue("backoff should grow at " + failures, current > previous);
			previous = current;
		}
	}

	@Test
	public void backoffIsCapped()
	{
		// A server that stays down must not push the retry interval to days.
		long cap = TimeUnit.MINUTES.toMillis(30);
		assertEquals(cap, AgamemnonCompanionPlugin.backoffMillis(50));
		assertEquals(cap, AgamemnonCompanionPlugin.backoffMillis(Integer.MAX_VALUE));
	}

	@Test
	public void backoffIsNeverZero()
	{
		// Zero would mean retrying flat out on every scheduled cycle.
		assertTrue(AgamemnonCompanionPlugin.backoffMillis(0) > 0);
		assertTrue(AgamemnonCompanionPlugin.backoffMillis(-5) > 0);
	}

	@Test
	public void reconnectsAfterLogoutOnTheSameAccount()
	{
		assertTrue(AgamemnonCompanionPlugin.shouldReconnectSession(
			ACCOUNT, ACCOUNT, SESSION, false));
	}

	@Test
	public void doesNotReconnectWhileAlreadyLoggedIn()
	{
		assertFalse(AgamemnonCompanionPlugin.shouldReconnectSession(
			ACCOUNT, ACCOUNT, SESSION, true));
	}

	@Test
	public void doesNotReconnectBeforeTheFirstSessionExists()
	{
		assertFalse(AgamemnonCompanionPlugin.shouldReconnectSession(
			ACCOUNT, ACCOUNT, null, false));
	}

	@Test
	public void doesNotReconnectOnAccountSwitch()
	{
		assertFalse(AgamemnonCompanionPlugin.shouldReconnectSession(
			ACCOUNT, ACCOUNT + 1, SESSION, false));
	}
}

package com.agamemnon.companion;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class AchievementStateTest
{
	private static Map<String, String> quests(String... pairs)
	{
		Map<String, String> map = new LinkedHashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			map.put(pairs[i], pairs[i + 1]);
		}
		return map;
	}

	private static Map<String, Boolean> flags(String name, boolean value)
	{
		Map<String, Boolean> map = new LinkedHashMap<>();
		map.put(name, value);
		return map;
	}

	private static Map<String, Integer> numbers(String name, int value)
	{
		Map<String, Integer> map = new LinkedHashMap<>();
		map.put(name, value);
		return map;
	}

	/** Records a block, defaulting everything but the quests. */
	private static boolean record(AchievementState state, Map<String, String> q)
	{
		return state.record(
			q,
			flags("ARDOUGNE_EASY", true),
			flags("VORKATH_KILLCOUNT_1", false),
			numbers("VORKATH", 3),
			numbers("ACHIEVEMENT_DIARY", 12_345),
			numbers("QUESTS_COMPLETED_COUNT", 41),
			1,
			3,
			false);
	}

	@Test
	public void aFirstBlockIsWorthSending()
	{
		AchievementState state = new AchievementState();

		assertTrue(record(state, quests("COOKS_ASSISTANT", "FINISHED")));
		assertTrue(state.hasPendingChanges());
	}

	@Test
	public void nothingIsPendingBeforeAnythingIsRead()
	{
		AchievementState state = new AchievementState();

		assertFalse(state.hasPendingChanges());
		assertNull(state.snapshot());
	}

	/**
	 * The reason the hash exists. The block is ~25 KB and barely moves; without
	 * this it would be resent on every login and every varbit change.
	 */
	@Test
	public void anUnchangedBlockIsNotResent()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "FINISHED"));
		state.confirmSent(state.snapshot());

		for (int i = 0; i < 50; i++)
		{
			assertFalse(record(state, quests("COOKS_ASSISTANT", "FINISHED")));
		}
		assertFalse(state.hasPendingChanges());
	}

	@Test
	public void aFinishedQuestIsAChange()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "IN_PROGRESS"));
		state.confirmSent(state.snapshot());

		assertTrue(record(state, quests("COOKS_ASSISTANT", "FINISHED")));
	}

	@Test
	public void aCombatAchievementIsAChange()
	{
		AchievementState state = new AchievementState();
		Map<String, String> q = quests("COOKS_ASSISTANT", "FINISHED");
		record(state, q);
		state.confirmSent(state.snapshot());

		assertTrue(state.record(
			q,
			flags("ARDOUGNE_EASY", true),
			flags("VORKATH_KILLCOUNT_1", true),
			numbers("VORKATH", 4),
			numbers("ACHIEVEMENT_DIARY", 12_345),
			numbers("QUESTS_COMPLETED_COUNT", 41),
			1,
			3,
			false));
	}

	@Test
	public void aRawDiaryVarpIsAChange()
	{
		AchievementState state = new AchievementState();
		Map<String, String> q = quests("COOKS_ASSISTANT", "FINISHED");
		record(state, q);
		state.confirmSent(state.snapshot());

		// One diary task ticked. We cannot say which, but we must not miss it.
		assertTrue(state.record(
			q,
			flags("ARDOUGNE_EASY", true),
			flags("VORKATH_KILLCOUNT_1", false),
			numbers("VORKATH", 3),
			numbers("ACHIEVEMENT_DIARY", 12_346),
			numbers("QUESTS_COMPLETED_COUNT", 41),
			1,
			3,
			false));
	}

	/** Key order is an implementation detail of whichever map was used. */
	@Test
	public void reorderingKeysIsNotAChange()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "FINISHED", "DRAGON_SLAYER_I", "NOT_STARTED"));
		state.confirmSent(state.snapshot());

		assertFalse(record(state,
			quests("DRAGON_SLAYER_I", "NOT_STARTED", "COOKS_ASSISTANT", "FINISHED")));
	}

	@Test
	public void theHashIsSixtyFourHexCharacters()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "FINISHED"));

		assertTrue(state.snapshot().hash.matches("[0-9a-f]{64}"));
	}

	@Test
	public void differentBlocksHashDifferently()
	{
		AchievementState a = new AchievementState();
		AchievementState b = new AchievementState();
		record(a, quests("COOKS_ASSISTANT", "FINISHED"));
		record(b, quests("COOKS_ASSISTANT", "NOT_STARTED"));

		assertNotEquals(a.snapshot().hash, b.snapshot().hash);
	}

	@Test
	public void confirmingClearsThePending()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "FINISHED"));

		state.confirmSent(state.snapshot());

		assertFalse(state.hasPendingChanges());
	}

	@Test
	public void aFailedSyncLeavesTheBlockPending()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "FINISHED"));

		// Request failed, so confirmSent is never called.
		state.snapshot();

		assertTrue(state.hasPendingChanges());
	}

	@Test
	public void aChangeDuringTheRequestKeepsTheStatePending()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "IN_PROGRESS"));

		AchievementState.Snapshot sent = state.snapshot();
		record(state, quests("COOKS_ASSISTANT", "FINISHED"));
		state.confirmSent(sent);

		assertTrue(state.hasPendingChanges());
		assertEquals("FINISHED", state.snapshot().quests.get("COOKS_ASSISTANT"));
	}

	@Test
	public void clearForgetsEverything()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "FINISHED"));
		state.confirmSent(state.snapshot());

		state.clear();

		assertFalse(state.hasPendingChanges());
		assertNull(state.snapshot());
		// The next account's identical block is still news, because nothing has
		// been sent for that account.
		assertTrue(record(state, quests("COOKS_ASSISTANT", "FINISHED")));
	}

	@Test
	public void aSnapshotIsIsolatedFromLaterWrites()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "IN_PROGRESS"));

		AchievementState.Snapshot snapshot = state.snapshot();
		record(state, quests("COOKS_ASSISTANT", "FINISHED"));

		assertEquals("IN_PROGRESS", snapshot.quests.get("COOKS_ASSISTANT"));
	}

	@Test
	public void theSnapshotCannotBeMutatedByItsCaller()
	{
		AchievementState state = new AchievementState();
		record(state, quests("COOKS_ASSISTANT", "FINISHED"));

		try
		{
			state.snapshot().quests.put("DRAGON_SLAYER_I", "FINISHED");
			throw new AssertionError("the snapshot should be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// The block goes to another thread; it must not be edited in flight.
		}
	}

	@Test
	public void anEmptyBlockStillHashes()
	{
		AchievementState state = new AchievementState();

		assertTrue(state.record(
			Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(),
			Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(),
			0, 0, false));
		assertTrue(state.snapshot().hash.matches("[0-9a-f]{64}"));
	}
}

