package com.agamemnon.companion;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SlayerStateTest
{
	private static final int ABYSSAL_DEMONS = 42;
	private static final int GARGOYLES = 43;
	private static final int CATACOMBS = 7;
	private static final int POINTS = 1_250;
	private static final int STREAK = 41;

	/** Records a task, defaulting everything but the monster and the count. */
	private static boolean record(SlayerState state, int monsterId, int remaining)
	{
		return state.record(monsterId, remaining, CATACOMBS, POINTS, STREAK);
	}

	@Test
	public void theFirstReadingIsABaselineNotAnAssignment()
	{
		SlayerState state = new SlayerState();

		// Logging in mid-task: the original size was never observed, so
		// claiming 87 were assigned would be a fabrication.
		assertFalse(record(state, ABYSSAL_DEMONS, 87));
		assertNull(state.snapshot().amountAssigned);
		assertTrue(state.hasPendingChanges());
	}

	@Test
	public void countingDownIsNotANewTask()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);

		assertFalse(record(state, ABYSSAL_DEMONS, 133));
		assertFalse(record(state, ABYSSAL_DEMONS, 90));
		assertEquals(90, state.snapshot().amountRemaining);
	}

	@Test
	public void aDifferentMonsterIsANewTask()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);

		assertTrue(record(state, GARGOYLES, 180));
		assertEquals(Integer.valueOf(180), state.snapshot().amountAssigned);
	}

	@Test
	public void theSameMonsterAgainIsStillANewTask()
	{
		// A slayer master will hand out the same monster twice running. The
		// count going up is the only thing that separates the two tasks.
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);
		record(state, ABYSSAL_DEMONS, 0);

		assertTrue(record(state, ABYSSAL_DEMONS, 120));
		assertEquals(Integer.valueOf(120), state.snapshot().amountAssigned);
	}

	@Test
	public void anyIncreaseCountsAsAnAssignment()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 3);

		// Kills only ever drive the count down.
		assertTrue(record(state, ABYSSAL_DEMONS, 4));
	}

	@Test
	public void anUnchangedReadingChangesNothing()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);
		state.confirmSent(state.snapshot());

		assertFalse(record(state, ABYSSAL_DEMONS, 134));
		assertFalse(state.hasPendingChanges());
	}

	@Test
	public void nothingIsPendingWithoutATask()
	{
		SlayerState state = new SlayerState();
		record(state, SlayerState.NO_TASK, 0);

		// The varps read zero when no task is assigned; that is not news.
		assertFalse(state.hasPendingChanges());
	}

	@Test
	public void anEmptySlotIsNeverANewTask()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);

		assertFalse(record(state, SlayerState.NO_TASK, 0));
	}

	@Test
	public void confirmingClearsThePendingFlag()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);

		state.confirmSent(state.snapshot());
		assertFalse(state.hasPendingChanges());
	}

	@Test
	public void aKillDuringTheRequestKeepsTheStatePending()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);

		SlayerState.Snapshot sent = state.snapshot();
		record(state, ABYSSAL_DEMONS, 133);
		state.confirmSent(sent);

		// The newer count still has to go out.
		assertTrue(state.hasPendingChanges());
		assertEquals(133, state.snapshot().amountRemaining);
	}

	@Test
	public void pointsAndStreakAreCarried()
	{
		SlayerState state = new SlayerState();
		state.record(ABYSSAL_DEMONS, 134, CATACOMBS, 1_300, 42);

		SlayerState.Snapshot snapshot = state.snapshot();
		assertEquals(1_300, snapshot.slayerPoints);
		assertEquals(42, snapshot.taskStreak);
		assertEquals(CATACOMBS, snapshot.locationId);
	}

	@Test
	public void aPointsChangeAloneStillNeedsSending()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);
		state.confirmSent(state.snapshot());

		// Finishing a task pays points without the count moving.
		assertFalse(state.record(ABYSSAL_DEMONS, 134, CATACOMBS, 1_300, STREAK));
		assertTrue(state.hasPendingChanges());
	}

	@Test
	public void clearForgetsEverything()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);

		state.clear();

		assertFalse(state.hasPendingChanges());
		assertEquals(SlayerState.NO_TASK, state.snapshot().monsterId);
		assertNull(state.snapshot().amountAssigned);
	}

	@Test
	public void clearMakesTheNextReadingABaselineAgain()
	{
		SlayerState state = new SlayerState();
		record(state, ABYSSAL_DEMONS, 134);
		state.clear();

		// After an account switch the plugin is watching a stranger's task
		// mid-flight, so the size is unknown again.
		assertFalse(record(state, GARGOYLES, 90));
		assertNull(state.snapshot().amountAssigned);
	}
}

package com.agamemnon.companion;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FarmingStateTest
{
	private static final String HERB = "FALADOR_2";
	private static final String TREE = "FALADOR_4";

	private static final long T0 = 1_700_000_000_000L;

	@Test
	public void theFirstSightingOfAPatchIsNews()
	{
		FarmingState state = new FarmingState();

		assertTrue(state.record(HERB, 32, T0));
		assertTrue(state.hasPendingChanges());
		assertEquals(1, state.snapshot().size());
	}

	/**
	 * The reason this class exists. A player standing in a farming region comes
	 * through here every game tick, and the varbits almost never move.
	 */
	@Test
	public void anUnchangedPatchIsNotResent()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);
		state.confirmSent(state.snapshot());

		for (int tick = 1; tick <= 100; tick++)
		{
			assertFalse(state.record(HERB, 32, T0 + tick * 600L));
		}

		assertFalse(state.hasPendingChanges());
	}

	/**
	 * The server extrapolates growth from when a state was first seen. Bumping
	 * the timestamp on every tick would keep resetting that clock and hold the
	 * harvest estimate permanently a stage behind.
	 */
	@Test
	public void anUnchangedPatchKeepsItsOriginalTimestamp()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);
		state.record(HERB, 32, T0 + 3_600_000L);

		assertEquals(T0, state.snapshot().get(0).observedAt);
	}

	@Test
	public void aChangedVarbitIsNews()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);
		state.confirmSent(state.snapshot());

		assertTrue(state.record(HERB, 33, T0 + 1_200_000L));
		assertEquals(33, state.snapshot().get(0).varbitValue);
		assertEquals(T0 + 1_200_000L, state.snapshot().get(0).observedAt);
	}

	@Test
	public void patchesAreTrackedIndependently()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);
		state.record(TREE, 48, T0);

		assertEquals(2, state.snapshot().size());

		state.confirmSent(state.snapshot());
		assertTrue(state.record(HERB, 33, T0 + 1));
		assertEquals(1, state.snapshot().size());
		assertEquals(HERB, state.snapshot().get(0).patchId);
	}

	@Test
	public void confirmingClearsThePending()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);

		state.confirmSent(state.snapshot());

		assertFalse(state.hasPendingChanges());
		assertTrue(state.snapshot().isEmpty());
	}

	@Test
	public void aFailedSyncLeavesEverythingPending()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);

		// Request failed, so confirmSent is never called.
		state.snapshot();

		assertTrue(state.hasPendingChanges());
	}

	@Test
	public void aPatchThatMovedDuringTheRequestStaysPending()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);

		List<FarmingState.Observation> sent = state.snapshot();
		// The herb grew while the request was on the wire.
		state.record(HERB, 33, T0 + 1_200_000L);
		state.confirmSent(sent);

		assertTrue(state.hasPendingChanges());
		assertEquals(33, state.snapshot().get(0).varbitValue);
	}

	@Test
	public void confirmingDoesNotDropAnUnrelatedPatch()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);

		List<FarmingState.Observation> sent = state.snapshot();
		state.record(TREE, 48, T0 + 600L);
		state.confirmSent(sent);

		assertEquals(1, state.snapshot().size());
		assertEquals(TREE, state.snapshot().get(0).patchId);
	}

	@Test
	public void clearForgetsEverything()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);

		state.clear();

		assertFalse(state.hasPendingChanges());
		// And the patch is news again, because this is a different account.
		assertTrue(state.record(HERB, 32, T0 + 1));
	}

	@Test
	public void aSnapshotIsIsolatedFromLaterWrites()
	{
		FarmingState state = new FarmingState();
		state.record(HERB, 32, T0);

		List<FarmingState.Observation> snapshot = state.snapshot();
		state.record(HERB, 99, T0 + 1);

		assertEquals(32, snapshot.get(0).varbitValue);
	}

	@Test
	public void anEmptyStateHasNothingToSend()
	{
		FarmingState state = new FarmingState();

		assertFalse(state.hasPendingChanges());
		assertTrue(state.snapshot().isEmpty());
	}
}

