import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class XpStateTest
{
	@Test
	public void tracksEveryRealSkill()
	{
		// 24 constants in net.runelite.api.Skill 1.12.36, ending at SAILING.
		assertEquals(24, Skill.values().length);
		assertEquals(Skill.values().length, XpState.TRACKED_SKILLS.size());
		assertTrue(XpState.TRACKED_SKILLS.contains(Skill.SAILING));
		assertFalse(XpState.TRACKED_SKILLS.stream()
			.anyMatch(skill -> "OVERALL".equals(skill.name())));
	}

	/**
	 * Pins down a trap worth knowing about: OVERALL is no longer an enum
	 * constant. It lingers as a deprecated static field holding null, so code
	 * that still reaches for it gets null rather than a Skill.
	 */
	@Test
	@SuppressWarnings("deprecation")
	public void overallIsANullStubRatherThanAConstant()
	{
		assertNull(Skill.OVERALL);
	}

	@Test
	public void firstSnapshotCarriesEverySkill()
	{
		XpState state = new XpState();
		state.record(Skill.ATTACK, 4_300_000);

		Map<String, Integer> changed = state.snapshot().getChangedSkills();

		assertEquals(XpState.TRACKED_SKILLS.size(), changed.size());
		assertEquals(Integer.valueOf(4_300_000), changed.get("ATTACK"));
		assertEquals(Integer.valueOf(0), changed.get("MINING"));
	}

	@Test
	public void laterSnapshotsCarryOnlyWhatMoved()
	{
		XpState state = new XpState();
		state.record(Skill.ATTACK, 1_000);
		state.confirmSent(state.snapshot());

		state.record(Skill.WOODCUTTING, 500);
		Map<String, Integer> changed = state.snapshot().getChangedSkills();

		assertEquals(1, changed.size());
		assertEquals(Integer.valueOf(500), changed.get("WOODCUTTING"));
	}

	/** Reads the skills off a "client" and marks the state fit to send. */
	private static XpState primed()
	{
		XpState state = new XpState();
		state.markPrimed();
		return state;
	}

	@Test
	public void nothingIsPendingBeforeTheSkillsHaveBeenRead()
	{
		XpState state = new XpState();

		// This is the login window: the account is known and the session is
		// open, but the stats packet has not landed. The array is all zeroes and
		// sendEverything is true, so without the primed gate a sync firing here
		// would report the account as having no XP at all.
		assertFalse(state.hasPendingChanges());
		assertFalse(state.isPrimed());
	}

	@Test
	public void primingOpensTheGate()
	{
		XpState state = new XpState();
		state.record(Skill.ATTACK, 4_300_000);
		state.markPrimed();

		assertTrue(state.isPrimed());
		assertTrue(state.hasPendingChanges());
	}

	@Test
	public void clearClosesTheGateAgain()
	{
		XpState state = primed();
		state.record(Skill.ATTACK, 1_000);

		// Switching accounts: the next account's skills have not been read yet,
		// so the zeroed array must not go out as that account's baseline.
		state.clear();

		assertFalse(state.isPrimed());
		assertFalse(state.hasPendingChanges());
	}

	@Test
	public void confirmedStateHasNothingPending()
	{
		XpState state = primed();
		state.record(Skill.ATTACK, 1_000);
		state.confirmSent(state.snapshot());

		assertFalse(state.hasPendingChanges());
		assertTrue(state.snapshot().getChangedSkills().isEmpty());
	}

	@Test
	public void xpEarnedWhileTheRequestIsInFlightIsNotLost()
	{
		XpState state = primed();
		state.record(Skill.ATTACK, 100);

		XpState.Snapshot sent = state.snapshot();
		// The player keeps training while the request is on the wire.
		state.record(Skill.ATTACK, 150);
		// The server acknowledges the older value.
		state.confirmSent(sent);

		assertTrue(state.hasPendingChanges());
		assertEquals(
			Integer.valueOf(150),
			state.snapshot().getChangedSkills().get("ATTACK"));
	}

	@Test
	public void aFailedSyncLeavesEverythingPending()
	{
		XpState state = primed();
		state.record(Skill.ATTACK, 1_000);

		// Request failed, so confirmSent is never called.
		state.snapshot();
		state.record(Skill.ATTACK, 1_200);

		// The whole accumulated state goes out again next cycle.
		assertTrue(state.hasPendingChanges());
		assertEquals(
			Integer.valueOf(1_200),
			state.snapshot().getChangedSkills().get("ATTACK"));
	}

	@Test
	public void aNullSkillIsIgnoredInsteadOfThrowing()
	{
		XpState state = new XpState();
		// This is what reaching for Skill.OVERALL actually hands over.
		state.record(null, 128_500_000);

		assertNull(state.snapshot().getChangedSkills().get("OVERALL"));
		assertEquals(0, state.snapshot().getTotalXp());
	}

	@Test
	public void totalXpSumsTheTrackedSkills()
	{
		XpState state = new XpState();
		state.record(Skill.ATTACK, 1_000);
		state.record(Skill.MINING, 2_500);

		assertEquals(3_500, state.snapshot().getTotalXp());
	}

	@Test
	public void totalXpSurvivesPastIntegerRange()
	{
		XpState state = new XpState();
		for (Skill skill : XpState.TRACKED_SKILLS)
		{
			state.record(skill, 200_000_000);
		}

		// 24 maxed skills is 4.8 billion, well past Integer.MAX_VALUE.
		assertEquals(200_000_000L * XpState.TRACKED_SKILLS.size(),
			state.snapshot().getTotalXp());
	}

	@Test
	public void clearDiscardsEverythingAndRebaselines()
	{
		XpState state = primed();
		state.record(Skill.ATTACK, 1_000);
		state.confirmSent(state.snapshot());

		state.clear();
		// The new account's skills are read before anything may be sent.
		state.record(Skill.ATTACK, 55);
		state.markPrimed();

		// Everything goes out again, as a fresh baseline for the new account.
		assertTrue(state.hasPendingChanges());
		Map<String, Integer> changed = state.snapshot().getChangedSkills();
		assertEquals(XpState.TRACKED_SKILLS.size(), changed.size());
		assertEquals(Integer.valueOf(55), changed.get("ATTACK"));
	}

	@Test
	public void snapshotIsIsolatedFromLaterWrites()
	{
		XpState state = new XpState();
		state.record(Skill.ATTACK, 100);

		XpState.Snapshot snapshot = state.snapshot();
		state.record(Skill.ATTACK, 999);

		assertEquals(Integer.valueOf(100), snapshot.getChangedSkills().get("ATTACK"));
	}
}

package com.agamemnon.companion;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Proves the generated patch table against RuneLite's own FarmingWorld.
 *
 * The table is generated, so most of it cannot drift. The exception is the five
 * coordinate checks in {@link FarmingPatches#inBounds}: those are transcribed
 * from bytecode, and a transcription is only worth what it has been checked
 * against. So they are checked against the real thing, at every coordinate of
 * every region where they are actually consulted.
 */
public class FarmingPatchesTest
{
	/** Region ids are (x >> 6) << 8 | (y >> 6), so this inverts that. */
	private static int regionBaseX(int regionId)
	{
		return (regionId >>> 8) << 6;
	}

	private static int regionBaseY(int regionId)
	{
		return (regionId & 0xFF) << 6;
	}

	private static final class Area
	{
		final int regionId;
		final Object region;
		final int bounds;

		Area(int regionId, Object region, int bounds)
		{
			this.regionId = regionId;
			this.region = region;
			this.bounds = bounds;
		}
	}

	/**
	 * Rebuilds RuneLite's region multimap and pairs each entry with the bounds
	 * id the generator assigned it. The ids follow the sorted order of the
	 * anonymous class names, which is what generate.py uses.
	 */
	private static List<Area> boundedAreas() throws Exception
	{
		ClassLoader cl = FarmingPatchesTest.class.getClassLoader();
		Class<?> worldCls = cl.loadClass(
			"net.runelite.client.plugins.timetracking.farming.FarmingWorld");
		Class<?> regionCls = cl.loadClass(
			"net.runelite.client.plugins.timetracking.farming.FarmingRegion");
		Class<?> multimapCls = cl.loadClass("com.google.common.collect.Multimap");

		Constructor<?> ctor = worldCls.getDeclaredConstructor();
		ctor.setAccessible(true);
		Object world = ctor.newInstance();

		Field regionsField = worldCls.getDeclaredField("regions");
		regionsField.setAccessible(true);
		Object regions = regionsField.get(world);

		Map<?, ?> asMap = (Map<?, ?>) multimapCls.getMethod("asMap").invoke(regions);

		// The generator numbers the bounds classes 1..n in sorted name order.
		Set<String> names = new java.util.TreeSet<>();
		for (Object value : asMap.values())
		{
			for (Object region : (Collection<?>) value)
			{
				if (!region.getClass().equals(regionCls))
				{
					names.add(region.getClass().getName());
				}
			}
		}

		List<String> ordered = new ArrayList<>(names);
		List<Area> areas = new ArrayList<>();

		for (Map.Entry<?, ?> entry : asMap.entrySet())
		{
			int regionId = (Integer) entry.getKey();
			for (Object region : (Collection<?>) entry.getValue())
			{
				boolean overrides = !region.getClass().equals(regionCls);
				int bounds = overrides
					? ordered.indexOf(region.getClass().getName()) + 1
					: 0;
				areas.add(new Area(regionId, region, bounds));
			}
		}

		return areas;
	}

	@Test
	public void boundsChecksMatchRuneLiteEverywhereTheyAreConsulted() throws Exception
	{
		Method isInBounds = Class
			.forName("net.runelite.client.plugins.timetracking.farming.FarmingRegion")
			.getMethod("isInBounds", WorldPoint.class);

		int compared = 0;
		int bounded = 0;

		for (Area area : boundedAreas())
		{
			if (area.bounds == 0)
			{
				continue;
			}
			bounded++;

			// Every tile of the region the player would have to be standing in
			// for this check to run, on all four planes.
			int baseX = regionBaseX(area.regionId);
			int baseY = regionBaseY(area.regionId);

			for (int plane = 0; plane < 4; plane++)
			{
				for (int x = baseX; x < baseX + 64; x++)
				{
					for (int y = baseY; y < baseY + 64; y++)
					{
						boolean expected = (Boolean) isInBounds.invoke(
							area.region, new WorldPoint(x, y, plane));
						boolean actual = FarmingPatches.inBounds(area.bounds, x, y, plane);

						if (expected != actual)
						{
							throw new AssertionError(String.format(
								"bounds %d disagrees at (%d, %d, plane %d) in region %d:"
									+ " RuneLite says %s, we say %s",
								area.bounds, x, y, plane, area.regionId, expected, actual));
						}
						compared++;
					}
				}
			}
		}

		// Guards against the loop silently doing nothing. Seventeen entries,
		// because the five bounds-checked regions are each reachable from
		// several neighbouring region ids.
		assertEquals("every bounds-checked entry should have been exercised", 17, bounded);
		assertTrue("expected a real sweep, got " + compared, compared > 250_000);
	}

	@Test
	public void unboundedAreasAlwaysMatch()
	{
		// Bounds id 0 means the region id alone settles it, which is what the
		// base FarmingRegion does.
		assertTrue(FarmingPatches.inBounds(0, 0, 0, 0));
		assertTrue(FarmingPatches.inBounds(0, 3200, 3200, 3));
	}

	@Test
	public void faladorAndPortSarimSplitTheirSharedRegion()
	{
		// Region 12083 holds both, and the split is the line y = 3272.
		FarmingPatches.Patch[] north = FarmingPatches.forLocation(12083, 3050, 3300, 0);
		FarmingPatches.Patch[] south = FarmingPatches.forLocation(12083, 3050, 3250, 0);

		assertTrue(ids(north).contains("FALADOR_2"));
		assertTrue(!ids(north).contains("PORT_SARIM"));

		assertTrue(ids(south).contains("PORT_SARIM"));
		assertTrue(!ids(south).contains("FALADOR_2"));
	}

	@Test
	public void aRegionWithNoPatchesReturnsNothing()
	{
		assertEquals(0, FarmingPatches.forLocation(0, 0, 0, 0).length);
		// A real region with nothing growable in it. Lumbridge does not
		// qualify: its allotment is readable from three region ids around it.
		assertEquals(0, FarmingPatches.forLocation(12849, 3200, 3140, 0).length);
	}

	@Test
	public void theFarmingGuildIsReadableFromItsNeighbours()
	{
		// Its patches are registered under six region ids, not just its own.
		assertTrue(FarmingPatches.forLocation(4922, 1249, 3726, 0).length > 0);
		assertTrue(FarmingPatches.forLocation(4665, 1180, 3560, 0).length > 0);
	}

	@Test
	public void everyPatchIdIsUniqueWithinALocation()
	{
		// Two areas can be readable at once; they must not both claim a patch.
		for (int regionId : new int[]{11317, 12083, 4922}) {
			FarmingPatches.Patch[] patches =
				FarmingPatches.forLocation(regionId, regionBaseX(regionId) + 32,
					regionBaseY(regionId) + 32, 0);
			assertEquals(patches.length, new HashSet<>(ids(patches)).size());
		}
	}

	@Test
	public void theTableCoversEveryRegionRuneLiteKnows() throws Exception
	{
		Set<Integer> expected = new HashSet<>();
		for (Area area : boundedAreas())
		{
			expected.add(area.regionId);
		}

		assertEquals(expected.size(), FarmingPatches.regionCount());
	}

	@Test
	public void patchesCarryARealVarbit()
	{
		FarmingPatches.Patch[] patches = FarmingPatches.forLocation(12083, 3050, 3300, 0);
		assertTrue(patches.length > 0);
		for (FarmingPatches.Patch patch : patches)
		{
			assertNotNull(patch.id);
			assertTrue("varbit should be a real id, got " + patch.varbit, patch.varbit > 0);
		}
	}

	private static List<String> ids(FarmingPatches.Patch[] patches)
	{
		List<String> out = new ArrayList<>();
		for (FarmingPatches.Patch patch : patches)
		{
			out.add(patch.id);
		}
		return out;
	}
}

package com.agamemnon.companion;

import java.util.Collections;
import java.util.Map;

/**
 * The body of a POST to /api/v1/sync, serialised by the injected Gson. Field
 * names are the wire contract with the API and must not be renamed casually.
 *
 * Nothing here describes any player other than the local account.
 */
final class XpSyncPayload
{
	static final int SCHEMA_VERSION = 1;

	private final int schemaVersion = SCHEMA_VERSION;

	/**
	 * A string, not a number. The account hash is a signed 64-bit value and
	 * JSON numbers lose precision above 2^53, so a JavaScript consumer would
	 * silently corrupt it.
	 */
	private final String accountHash;
	private final String sessionId;
	private final String displayName;
	private final String accountType;
	private final String worldType;
	private final long clientTimestamp;
	private final boolean sessionEnd;

	/** Absolute XP per skill, not deltas. The server computes the deltas. */
	private final Map<String, Integer> skills;
	private final long totalXp;

	XpSyncPayload(
		long accountHash,
		String sessionId,
		String displayName,
		String accountType,
		String worldType,
		long clientTimestamp,
		boolean sessionEnd,
		Map<String, Integer> skills,
		long totalXp)
	{
		this.accountHash = Long.toString(accountHash);
		this.sessionId = sessionId;
		this.displayName = displayName;
		this.accountType = accountType;
		this.worldType = worldType;
		this.clientTimestamp = clientTimestamp;
		this.sessionEnd = sessionEnd;
		this.skills = skills == null ? Collections.emptyMap() : skills;
		this.totalXp = totalXp;
	}
}

package com.agamemnon.companion;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;

/**
 * Holds the quest, diary and combat achievement block, and decides whether it
 * is worth sending.
 *
 * These three are almost static: a player finishes a quest now and then, and
 * nothing else in here moves for hours. The block is also large — around eight
 * hundred entries — so sending it on every varbit change would mean tens of
 * kilobytes a tick, which is exactly the kind of traffic that gets a plugin
 * rejected from the Plugin Hub.
 *
 * So the block is hashed and only sent when the hash moves. The hash is taken
 * over a canonical rendering with sorted keys, so an incidental reordering does
 * not read as a change.
 *
 * Two threads touch this: the block is built on the client thread, while the
 * sync thread reads it. One dedicated lock guards all of it.
 */
final class AchievementState
{
	private final Object lock = new Object();

	private Map<String, String> quests = Collections.emptyMap();
	private Map<String, Boolean> diaryTiers = Collections.emptyMap();
	private Map<String, Boolean> combatTasks = Collections.emptyMap();
	private Map<String, Integer> combatTotals = Collections.emptyMap();
	private Map<String, Integer> diaryVarps = Collections.emptyMap();
	private Map<String, Integer> questCounts = Collections.emptyMap();
	private int questPoints;
	private int combatLevel;
	private boolean membersWorld;

	private String hash;
	private String sentHash;

	/**
	 * Replaces the block. Returns true if it differs from what was last sent.
	 *
	 * Nothing is recorded until every part has been read: a half-built block
	 * would hash differently from the same account fully loaded, and would then
	 * be sent, stored, and immediately superseded.
	 */
	boolean record(
		Map<String, String> quests,
		Map<String, Boolean> diaryTiers,
		Map<String, Boolean> combatTasks,
		Map<String, Integer> combatTotals,
		Map<String, Integer> diaryVarps,
		Map<String, Integer> questCounts,
		int questPoints,
		int combatLevel,
		boolean membersWorld)
	{
		String computed = computeHash(
			quests, diaryTiers, combatTasks, combatTotals, diaryVarps, questCounts,
			questPoints, combatLevel, membersWorld);

		synchronized (lock)
		{
			this.quests = Collections.unmodifiableMap(new LinkedHashMap<>(quests));
			this.diaryTiers = Collections.unmodifiableMap(new LinkedHashMap<>(diaryTiers));
			this.combatTasks = Collections.unmodifiableMap(new LinkedHashMap<>(combatTasks));
			this.combatTotals = Collections.unmodifiableMap(new LinkedHashMap<>(combatTotals));
			this.diaryVarps = Collections.unmodifiableMap(new LinkedHashMap<>(diaryVarps));
			this.questCounts = Collections.unmodifiableMap(new LinkedHashMap<>(questCounts));
			this.questPoints = questPoints;
			this.combatLevel = combatLevel;
			this.membersWorld = membersWorld;
			this.hash = computed;

			return !computed.equals(sentHash);
		}
	}

	boolean hasPendingChanges()
	{
		synchronized (lock)
		{
			return hash != null && !hash.equals(sentHash);
		}
	}

	/**
	 * The block to send, or null if nothing has been read yet. The snapshot is
	 * what {@link #confirmSent} must be handed back — confirming a later read
	 * would mark unsent state as delivered.
	 */
	Snapshot snapshot()
	{
		synchronized (lock)
		{
			if (hash == null)
			{
				return null;
			}
			return new Snapshot(
				quests, diaryTiers, combatTasks, combatTotals, diaryVarps, questCounts,
				questPoints, combatLevel, membersWorld, hash);
		}
	}

	/** Called only once the server has acknowledged the snapshot. */
	void confirmSent(Snapshot snapshot)
	{
		synchronized (lock)
		{
			sentHash = snapshot.hash;
		}
	}

	/** Throws away everything, unsent. Used on logout and on account switch. */
	void clear()
	{
		synchronized (lock)
		{
			quests = Collections.emptyMap();
			diaryTiers = Collections.emptyMap();
			combatTasks = Collections.emptyMap();
			combatTotals = Collections.emptyMap();
			diaryVarps = Collections.emptyMap();
			questCounts = Collections.emptyMap();
			questPoints = 0;
			combatLevel = 0;
			membersWorld = false;
			hash = null;
			sentHash = null;
		}
	}

	/**
	 * SHA-256 over a canonical rendering: sections in a fixed order, keys sorted
	 * inside each. Two blocks that mean the same thing hash the same.
	 */
	private static String computeHash(
		Map<String, String> quests,
		Map<String, Boolean> diaryTiers,
		Map<String, Boolean> combatTasks,
		Map<String, Integer> combatTotals,
		Map<String, Integer> diaryVarps,
		Map<String, Integer> questCounts,
		int questPoints,
		int combatLevel,
		boolean membersWorld)
	{
		StringBuilder canonical = new StringBuilder();
		append(canonical, "quests", quests);
		append(canonical, "diaryTiers", diaryTiers);
		append(canonical, "combatTasks", combatTasks);
		append(canonical, "combatTotals", combatTotals);
		append(canonical, "diaryVarps", diaryVarps);
		append(canonical, "questCounts", questCounts);
		canonical.append("questPoints=").append(questPoints).append(';');
		canonical.append("combatLevel=").append(combatLevel).append(';');
		canonical.append("membersWorld=").append(membersWorld).append(';');

		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] bytes = digest.digest(canonical.toString().getBytes(StandardCharsets.UTF_8));

			StringBuilder hex = new StringBuilder(bytes.length * 2);
			for (byte b : bytes)
			{
				hex.append(Character.forDigit((b >> 4) & 0xF, 16));
				hex.append(Character.forDigit(b & 0xF, 16));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			// SHA-256 is required of every Java platform; this cannot happen.
			throw new IllegalStateException("SHA-256 unavailable", e);
		}
	}

	private static void append(StringBuilder out, String section, Map<String, ?> values)
	{
		out.append(section).append('{');
		for (Map.Entry<String, ?> entry : new TreeMap<String, Object>(values).entrySet())
		{
			out.append(entry.getKey()).append('=').append(entry.getValue()).append(';');
		}
		out.append('}');
	}

	static final class Snapshot
	{
		final Map<String, String> quests;
		final Map<String, Boolean> diaryTiers;
		final Map<String, Boolean> combatTasks;
		final Map<String, Integer> combatTotals;
		final Map<String, Integer> diaryVarps;
		final Map<String, Integer> questCounts;
		final int questPoints;
		final int combatLevel;
		final boolean membersWorld;
		final String hash;

		private Snapshot(
			Map<String, String> quests,
			Map<String, Boolean> diaryTiers,
			Map<String, Boolean> combatTasks,
			Map<String, Integer> combatTotals,
			Map<String, Integer> diaryVarps,
			Map<String, Integer> questCounts,
			int questPoints,
			int combatLevel,
			boolean membersWorld,
			String hash)
		{
			this.quests = quests;
			this.diaryTiers = diaryTiers;
			this.combatTasks = combatTasks;
			this.combatTotals = combatTotals;
			this.diaryVarps = diaryVarps;
			this.questCounts = questCounts;
			this.questPoints = questPoints;
			this.combatLevel = combatLevel;
			this.membersWorld = membersWorld;
			this.hash = hash;
		}
	}
}

package com.agamemnon.companion;

import java.util.EnumSet;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.WorldType;

/**
 * Turns raw client values into the strings that go on the wire. Kept separate
 * from the plugin so it can be tested without standing up a client.
 */
final class AccountDetails
{
	/**
	 * Worlds whose XP is artificial and must never reach the tracker. Names
	 * verified against {@code net.runelite.api.WorldType} in runelite-api
	 * 1.12.36 — Leagues worlds report as SEASONAL, and there is no LEAGUE
	 * constant.
	 */
	private static final Set<WorldType> ARTIFICIAL_WORLDS = EnumSet.of(
		WorldType.SEASONAL,
		WorldType.DEADMAN,
		WorldType.BETA_WORLD,
		WorldType.TOURNAMENT_WORLD,
		WorldType.NOSAVE_MODE,
		WorldType.QUEST_SPEEDRUNNING);

	private AccountDetails()
	{
	}

	/**
	 * True if XP earned here is not comparable to the main game. The plugin
	 * skips syncing entirely on these worlds.
	 */
	static boolean isArtificialWorld(Set<WorldType> worldTypes)
	{
		if (worldTypes == null)
		{
			return false;
		}

		for (WorldType worldType : worldTypes)
		{
			if (ARTIFICIAL_WORLDS.contains(worldType))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * {@code Client.getWorldType()} returns a set, so it goes on the wire as a
	 * comma-separated list rather than losing everything but one member.
	 */
	static String describeWorldTypes(Set<WorldType> worldTypes)
	{
		if (worldTypes == null || worldTypes.isEmpty())
		{
			return "";
		}

		return worldTypes.stream()
			.map(Enum::name)
			.collect(Collectors.joining(","));
	}

	/**
	 * Maps the ironman varbit ({@code VarbitID.IRONMAN}, 1777) to a name.
	 *
	 * Anything outside the known range is passed through as UNKNOWN_n rather
	 * than guessed at — the server stores the string as-is, so a value added by
	 * a future update lands in the data intact instead of being mislabelled.
	 */
	static String describeAccountType(int varbitValue)
	{
		switch (varbitValue)
		{
			case 0:
				return "NORMAL";
			case 1:
				return "IRONMAN";
			case 2:
				return "ULTIMATE_IRONMAN";
			case 3:
				return "HARDCORE_IRONMAN";
			case 4:
				return "GROUP_IRONMAN";
			case 5:
				return "HARDCORE_GROUP_IRONMAN";
			case 6:
				return "UNRANKED_GROUP_IRONMAN";
			default:
				return "UNKNOWN_" + varbitValue;
		}
	}
}

package com.agamemnon.companion;

import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;

/**
 * Resolves slayer task and area ids to readable names using the game's own
 * data tables.
 *
 * Deliberately not a hardcoded lookup table: those go stale the moment Jagex
 * adds a task, and the client already ships the mapping. When an id does not
 * resolve, the caller sends the raw id and the server keeps it — inventing a
 * name would be worse than admitting the gap.
 *
 * Every method here reads client data and must be called on the client thread.
 */
@Slf4j
final class SlayerNames
{
	private SlayerNames()
	{
	}

	@Nullable
	static String monster(Client client, int monsterId)
	{
		return lookup(
			client,
			DBTableID.SlayerTask.ID,
			DBTableID.SlayerTask.COL_ID,
			DBTableID.SlayerTask.COL_NAME_UPPERCASE,
			monsterId);
	}

	@Nullable
	static String location(Client client, int locationId)
	{
		return lookup(
			client,
			DBTableID.SlayerArea.ID,
			DBTableID.SlayerArea.COL_AREA_ID,
			DBTableID.SlayerArea.COL_AREA_TEXT,
			locationId);
	}

	/**
	 * Finds the row whose key column holds {@code value} and returns the first
	 * string in the requested column.
	 */
	@Nullable
	private static String lookup(Client client, int table, int keyColumn, int valueColumn, int value)
	{
		if (value <= 0)
		{
			return null;
		}

		try
		{
			java.util.List<Integer> rows =
				client.getDBRowsByValue(table, keyColumn, 0, value);

			if (rows == null || rows.isEmpty())
			{
				return null;
			}

			Object[] field = client.getDBTableField(rows.get(0), valueColumn, 0);
			if (field == null || field.length == 0 || !(field[0] instanceof String))
			{
				return null;
			}

			String name = ((String) field[0]).trim();
			return name.isEmpty() ? null : name;
		}
		catch (RuntimeException e)
		{
			// A table shape that changed under us is not worth breaking the
			// sync over; the raw id still goes to the server.
			log.debug("could not resolve slayer name from table {} value {}", table, value, e);
			return null;
		}
	}
}

package com.agamemnon.companion;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.Skill;

/**
 * Holds XP per skill and works out what still needs sending.
 *
 * Two threads touch this. {@code record} is called from the client thread on
 * every {@code StatChanged}; {@code snapshot} and {@code confirmSent} run on the
 * executor thread that performs the sync. Every access goes through one
 * dedicated lock — a lock on the plugin instance itself would be visible to
 * RuneLite and to any other code holding a reference to it.
 *
 * The sync protocol sends absolute XP rather than deltas, which is what makes a
 * dropped request harmless: nothing is confirmed until the server says so, so
 * the next cycle simply resends the accumulated state.
 */
final class XpState
{
	/**
	 * The account total is not a skill and never becomes a skill row; it goes
	 * out as the payload's totalXp field instead.
	 *
	 * In runelite-api 1.12.36 there is nothing to filter: {@code Skill.OVERALL}
	 * is no longer an enum constant at all. It survives only as a deprecated
	 * static field holding {@code null}, kept for source compatibility, so
	 * {@code Skill.values()} is 24 real skills ending at SAILING. The filter
	 * stays as a guard in case a future release reintroduces it, and matches on
	 * the name so it keeps compiling either way.
	 */
	private static final String OVERALL = "OVERALL";

	/** Every skill the tracker records, in enum order. */
	static final List<Skill> TRACKED_SKILLS = Collections.unmodifiableList(
		Arrays.stream(Skill.values())
			.filter(skill -> !OVERALL.equals(skill.name()))
			.collect(Collectors.toList()));

	/** Indexed by ordinal so the hot path is an array read, not a string compare. */
	private static final boolean[] TRACKED = buildTrackedFlags();

	private static boolean[] buildTrackedFlags()
	{
		boolean[] flags = new boolean[Skill.values().length];
		for (Skill skill : TRACKED_SKILLS)
		{
			flags[skill.ordinal()] = true;
		}
		return flags;
	}

	private final Object lock = new Object();
	private final int[] current = new int[Skill.values().length];
	private final int[] lastSent = new int[Skill.values().length];

	/**
	 * True until a sync has been confirmed for this session, so the first
	 * payload carries every skill and the server gets a complete baseline.
	 */
	private boolean sendEverything = true;

	/**
	 * False until the real skills have been read off a logged-in client.
	 *
	 * Without this the zeroed array left by {@link #clear} is indistinguishable
	 * from an account with no XP, and since {@code sendEverything} starts true,
	 * a sync landing between login and the stats packet would ship 24 zeroes as
	 * though they were fact.
	 */
	private boolean primed;

	/** Called once the client has been confirmed to hold real skill data. */
	void markPrimed()
	{
		synchronized (lock)
		{
			primed = true;
		}
	}

	/**
	 * Marks the start of a new server session without discarding XP readings.
	 *
	 * The next sync carries every skill so the new session row gets a baseline
	 * even if nothing changed while the player was on the login screen.
	 */
	void beginSession()
	{
		synchronized (lock)
		{
			sendEverything = true;
		}
	}

	boolean isPrimed()
	{
		synchronized (lock)
		{
			return primed;
		}
	}

	void record(Skill skill, int xp)
	{
		// The null check is not paranoia: Skill.OVERALL is a static field whose
		// value is null, so anything still reaching for it arrives here as null
		// rather than as a constant.
		if (skill == null || !TRACKED[skill.ordinal()])
		{
			return;
		}

		synchronized (lock)
		{
			current[skill.ordinal()] = xp;
		}
	}

	/** Throws away all state, unsent. Used on logout and on account switch. */
	void clear()
	{
		synchronized (lock)
		{
			Arrays.fill(current, 0);
			Arrays.fill(lastSent, 0);
			sendEverything = true;
			primed = false;
		}
	}

	boolean hasPendingChanges()
	{
		synchronized (lock)
		{
			if (!primed)
			{
				return false;
			}

			if (sendEverything)
			{
				return true;
			}

			for (Skill skill : TRACKED_SKILLS)
			{
				if (current[skill.ordinal()] != lastSent[skill.ordinal()])
				{
					return true;
				}
			}
			return false;
		}
	}

	/**
	 * Copies the current state and lists the skills that have moved since the
	 * last confirmed send. The copy is what {@link #confirmSent} must be given
	 * back — confirming against a later read would silently discard any XP
	 * gained while the request was in flight.
	 */
	Snapshot snapshot()
	{
		synchronized (lock)
		{
			Map<String, Integer> changed = new LinkedHashMap<>();
			long total = 0;

			for (Skill skill : TRACKED_SKILLS)
			{
				int xp = current[skill.ordinal()];
				total += xp;

				if (sendEverything || xp != lastSent[skill.ordinal()])
				{
					changed.put(skill.name(), xp);
				}
			}

			return new Snapshot(Arrays.copyOf(current, current.length), changed, total);
		}
	}

	/** Called only once the server has acknowledged the snapshot. */
	void confirmSent(Snapshot snapshot)
	{
		synchronized (lock)
		{
			System.arraycopy(snapshot.values, 0, lastSent, 0, lastSent.length);
			sendEverything = false;
		}
	}

	static final class Snapshot
	{
		private final int[] values;
		private final Map<String, Integer> changedSkills;
		private final long totalXp;

		private Snapshot(int[] values, Map<String, Integer> changedSkills, long totalXp)
		{
			this.values = values;
			this.changedSkills = Collections.unmodifiableMap(changedSkills);
			this.totalXp = totalXp;
		}

		Map<String, Integer> getChangedSkills()
		{
			return changedSkills;
		}

		long getTotalXp()
		{
			return totalXp;
		}
	}
}

