package com.agamemnon.companion;

import java.util.Map;

/**
 * The body of a POST to /api/v1/achievements. Field names are the wire contract.
 *
 * The payload carries the hash the plugin computed. The server compares it
 * against what it holds and skips the write when they match, so a plugin that
 * lost its own memory of what it sent — a restart — costs one request rather
 * than a rewrite.
 *
 * Only the local account's own progress; nothing here describes another player.
 */
final class AchievementSyncPayload
{
	private final int schemaVersion = XpSyncPayload.SCHEMA_VERSION;

	private final String accountHash;

	/** Quest name to NOT_STARTED / IN_PROGRESS / FINISHED. */
	private final Map<String, String> quests;

	/** Region and difficulty, e.g. ARDOUGNE_EASY, to whether it is complete. */
	private final Map<String, Boolean> diaryTiers;

	private final Map<String, Boolean> combatTasks;

	/** Completion counts per boss. */
	private final Map<String, Integer> combatTotals;

	/**
	 * The per-task diary bitfields, undecoded.
	 *
	 * Which bit is which task is recorded nowhere in RuneLite, so sending
	 * the raw values keeps the data honest: the server stores what the game
	 * said, and can learn the mapping later without a plugin release.
	 */
	private final Map<String, Integer> diaryVarps;

	/**
	 * The game's own tallies: completed, total, miniquests, subquests.
	 *
	 * Counting the quest list ourselves would overcount, because RuneLite's
	 * Quest enum mixes miniquests in and the game does not count those.
	 */
	private final Map<String, Integer> questCounts;

	/** Quest points from {@code VarPlayerID.QP}. */
	private final int questPoints;

	/** Local player's combat level. */
	private final int combatLevel;

	/**
	 * Whether the current world is a members world. Used as the journal's
	 * membership gate for available-quests — not a bond-days countdown.
	 */
	private final boolean membersWorld;

	private final String payloadHash;
	private final long clientTimestamp;

	AchievementSyncPayload(
		long accountHash,
		AchievementState.Snapshot snapshot,
		long clientTimestamp)
	{
		this.accountHash = Long.toString(accountHash);
		this.quests = snapshot.quests;
		this.diaryTiers = snapshot.diaryTiers;
		this.combatTasks = snapshot.combatTasks;
		this.combatTotals = snapshot.combatTotals;
		this.diaryVarps = snapshot.diaryVarps;
		this.questCounts = snapshot.questCounts;
		this.questPoints = snapshot.questPoints;
		this.combatLevel = snapshot.combatLevel;
		this.membersWorld = snapshot.membersWorld;
		this.payloadHash = snapshot.hash;
		this.clientTimestamp = clientTimestamp;
	}
}

package com.agamemnon.companion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;

/**
 * Reads each quest's journal requirements out of the game's DB table.
 *
 * The values are not in RuneLite's jar — only the column layout is — so this
 * has to run against a live {@link Client}. The result is static game data
 * (not the player's progress); the plugin hashes it and only re-sends when
 * the catalog itself moves.
 *
 * Informational only: nothing here clicks, walks, or otherwise acts in the
 * game. Jagex's third-party guidelines allow read-only account helpers of
 * this kind.
 *
 * Client thread only.
 */
@Slf4j
final class QuestRequirements
{
	private QuestRequirements()
	{
	}

	/**
	 * One entry per {@link Quest} enum value, keyed by the enum name so it
	 * lines up with the quests map already synced for achievements.
	 */
	static Map<String, Entry> readAll(Client client)
	{
		Map<Integer, String> nameById = new LinkedHashMap<>();
		for (Quest quest : Quest.values())
		{
			nameById.put(quest.getId(), quest.name());
		}

		Map<String, Entry> out = new LinkedHashMap<>();
		for (Quest quest : Quest.values())
		{
			try
			{
				out.put(quest.name(), readOne(client, quest, nameById));
			}
			catch (RuntimeException e)
			{
				log.debug("could not read requirements for {}", quest.name(), e);
			}
		}
		return out;
	}

	private static Entry readOne(Client client, Quest quest, Map<Integer, String> nameById)
	{
		int row = quest.getId();

		String displayName = stringField(client, row, DBTableID.Quest.COL_DISPLAYNAME);
		if (displayName == null || displayName.isEmpty())
		{
			displayName = quest.getName();
		}

		boolean members = boolField(client, row, DBTableID.Quest.COL_MEMBERS);
		int questPointsReq = intField(client, row, DBTableID.Quest.COL_REQUIREMENT_QUESTPOINTS);
		// The journal table often stores 3 here as a floor value, not a real gate.
		int combatReq = normalizeCombatReq(intField(client, row, DBTableID.Quest.COL_REQUIREMENT_COMBAT));
		boolean boostable = boolField(client, row, DBTableID.Quest.COL_REQUIREMENTS_BOOSTABLE);
		Integer difficulty = optionalInt(client, row, DBTableID.Quest.COL_DIFFICULTY);
		Integer length = optionalInt(client, row, DBTableID.Quest.COL_LENGTH);

		List<SkillReq> skills = readSkillReqs(client, row);
		List<String> prereqs = readQuestPrereqs(client, row, nameById);

		String kind = kindFor(quest);
		return new Entry(
			kind,
			displayName,
			members,
			questPointsReq,
			combatReq,
			boostable,
			difficulty,
			length,
			skills,
			prereqs);
	}

	/**
	 * Skill tuples are the column that most often blows up on a live Client.
	 * Failure here used to drop the whole quest from the catalog, which made
	 * the dashboard's Done chip count only the skill-free quests.
	 */
	private static List<SkillReq> readSkillReqs(Client client, int row)
	{
		List<SkillReq> skills = new ArrayList<>();
		try
		{
			readSkillColumn(client, row, skills);
		}
		catch (RuntimeException e)
		{
			log.debug("could not read skill requirements for quest row {}", row, e);
		}
		return skills;
	}

	/**
	 * {@code COL_REQUIREMENT_STATS} is typed {@code (stat, integer)}. The client
	 * may return the whole column in one tuple, one pair per tuple, or tuples
	 * with a dangling stat at the end ({@code [6, 65, 12]}). Pair across tuples
	 * with a carry — never stop after the first tuple.
	 */
	private static void readSkillColumn(Client client, int row, List<SkillReq> skills)
	{
		Object pendingStat = null;
		for (int tupleIndex = 0; ; tupleIndex++)
		{
			Object[] tuple = client.getDBTableField(
				row, DBTableID.Quest.COL_REQUIREMENT_STATS, tupleIndex);
			if (tuple == null || tuple.length == 0)
			{
				break;
			}

			int index = 0;
			if (pendingStat != null)
			{
				appendSkillPair(skills, pendingStat, tuple[0]);
				index = 1;
				pendingStat = null;
			}

			for (int i = index; i + 1 < tuple.length; i += 2)
			{
				appendSkillPair(skills, tuple[i], tuple[i + 1]);
			}

			if ((tuple.length - index) % 2 == 1)
			{
				pendingStat = tuple[tuple.length - 1];
			}
		}
	}

	/**
	 * The journal DB table is not fully populated at {@code LOGGED_IN}. Reading
	 * too early yields pairs like Magic 12 (stat 6, next skill id 12) instead of
	 * Magic 65. Two multi-skill probes must both look sane before the catalog
	 * is uploaded — partial reads often pass one quest with skill-id levels.
	 */
	static boolean isCatalogReady(Client client)
	{
		return probeReady(client, Quest.LUNAR_DIPLOMACY, 7, 30, 2)
			&& probeReady(client, Quest.COLD_WAR, 5, 15, 2);
	}

	private static boolean probeReady(
		Client client,
		Quest quest,
		int minSkills,
		int minMaxLevel,
		int minHighLevels)
	{
		List<SkillReq> skills = new ArrayList<>();
		try
		{
			readSkillColumn(client, quest.getId(), skills);
		}
		catch (RuntimeException e)
		{
			return false;
		}

		if (skills.size() < minSkills)
		{
			return false;
		}

		int maxLevel = 0;
		int highLevels = 0;
		for (SkillReq req : skills)
		{
			maxLevel = Math.max(maxLevel, req.level);
			if (req.level >= 30)
			{
				highLevels++;
			}
		}

		return maxLevel >= minMaxLevel && highLevels >= minHighLevels;
	}

	/** JSON array for debug logging, e.g. {@code [{"skill":"HUNTER","level":10},...]}. */
	static String formatSkillReqs(List<SkillReq> skills)
	{
		StringBuilder out = new StringBuilder("[");
		for (int i = 0; i < skills.size(); i++)
		{
			SkillReq req = skills.get(i);
			if (i > 0)
			{
				out.append(',');
			}
			out.append("{\"skill\":\"").append(req.skill)
				.append("\",\"level\":").append(req.level).append('}');
		}
		out.append(']');
		return out.toString();
	}

	/** Raw tuples for debugging partial journal loads. Client thread only. */
	static String dumpRequirementColumn(Client client, int row)
	{
		StringBuilder out = new StringBuilder("[");
		for (int tupleIndex = 0; ; tupleIndex++)
		{
			Object[] tuple = client.getDBTableField(
				row, DBTableID.Quest.COL_REQUIREMENT_STATS, tupleIndex);
			if (tuple == null || tuple.length == 0)
			{
				break;
			}
			if (tupleIndex > 0)
			{
				out.append(',');
			}
			out.append('[');
			for (int i = 0; i < tuple.length; i++)
			{
				if (i > 0)
				{
					out.append(',');
				}
				out.append(formatDebugValue(tuple[i]));
			}
			out.append(']');
		}
		out.append(']');
		return out.toString();
	}

	private static String formatDebugValue(Object value)
	{
		if (value instanceof Skill)
		{
			return ((Skill) value).name();
		}
		return String.valueOf(value);
	}

	private static void appendSkillPair(List<SkillReq> skills, Object stat, Object levelValue)
	{
		Integer skillId = statId(stat);
		Integer level = asInt(levelValue);
		if (skillId == null || level == null || level <= 0)
		{
			return;
		}

		String skillName = skillName(skillId);
		if (skillName != null)
		{
			skills.add(new SkillReq(skillName, level));
		}
	}

	private static List<String> readQuestPrereqs(
		Client client, int row, Map<Integer, String> nameById)
	{
		List<String> prereqs = new ArrayList<>();
		try
		{
			readQuestColumn(client, row, nameById, prereqs);
		}
		catch (RuntimeException e)
		{
			log.debug("could not read quest prerequisites for quest row {}", row, e);
		}
		return prereqs;
	}

	/** Same multi-tuple shapes as {@link #readSkillColumn}, but dbrow values. */
	private static void readQuestColumn(
		Client client, int row, Map<Integer, String> nameById, List<String> prereqs)
	{
		for (int tupleIndex = 0; ; tupleIndex++)
		{
			Object[] tuple = client.getDBTableField(
				row, DBTableID.Quest.COL_REQUIREMENT_QUESTS, tupleIndex);
			if (tuple == null || tuple.length == 0)
			{
				break;
			}

			for (Object value : tuple)
			{
				appendQuestPrereq(nameById, prereqs, value);
			}
		}
	}

	private static void appendQuestPrereq(
		Map<Integer, String> nameById, List<String> prereqs, Object value)
	{
		Integer prereqRow = asInt(value);
		if (prereqRow == null)
		{
			return;
		}

		String name = nameById.get(prereqRow);
		if (name != null)
		{
			prereqs.add(name);
		}
	}

	private static int normalizeCombatReq(int combatReq)
	{
		return combatReq <= 3 ? 0 : combatReq;
	}

	private static Integer statId(Object value)
	{
		if (value instanceof Skill)
		{
			Skill skill = (Skill) value;
			return skill == Skill.OVERALL ? null : skill.ordinal();
		}
		return asInt(value);
	}

	private static String kindFor(Quest quest)
	{
		for (AchievementVarbits.KindEntry entry : AchievementVarbits.QUEST_KINDS)
		{
			if (entry.name.equals(quest.name()))
			{
				return entry.kind;
			}
		}
		return "QUEST";
	}

	private static String skillName(int skillId)
	{
		Skill[] skills = Skill.values();
		if (skillId < 0 || skillId >= skills.length)
		{
			return null;
		}
		Skill skill = skills[skillId];
		return skill == Skill.OVERALL ? null : skill.name();
	}

	private static String stringField(Client client, int row, int column)
	{
		Object[] field = client.getDBTableField(row, column, 0);
		if (field == null || field.length == 0 || !(field[0] instanceof String))
		{
			return null;
		}
		return ((String) field[0]).trim();
	}

	private static boolean boolField(Client client, int row, int column)
	{
		Object[] field = client.getDBTableField(row, column, 0);
		if (field == null || field.length == 0)
		{
			return false;
		}
		Object value = field[0];
		if (value instanceof Boolean)
		{
			return (Boolean) value;
		}
		Integer n = asInt(value);
		return n != null && n != 0;
	}

	private static int intField(Client client, int row, int column)
	{
		Integer value = optionalInt(client, row, column);
		return value == null ? 0 : value;
	}

	private static Integer optionalInt(Client client, int row, int column)
	{
		Object[] field = client.getDBTableField(row, column, 0);
		if (field == null || field.length == 0)
		{
			return null;
		}
		return asInt(field[0]);
	}

	private static Integer asInt(Object value)
	{
		if (value instanceof Integer)
		{
			return (Integer) value;
		}
		if (value instanceof Number)
		{
			return ((Number) value).intValue();
		}
		// Some DB tuple slots arrive as a one-element Object[].
		if (value instanceof Object[])
		{
			Object[] nested = (Object[]) value;
			if (nested.length > 0)
			{
				return asInt(nested[0]);
			}
		}
		return null;
	}

	/** Wire shape — field names are the JSON contract. Gson reads these. */
	static final class Entry
	{
		final String kind;
		final String displayName;
		final boolean members;
		final int questPoints;
		final int combatLevel;
		final boolean boostable;
		final Integer difficulty;
		final Integer length;
		final List<SkillReq> skills;
		final List<String> quests;

		Entry(
			String kind,
			String displayName,
			boolean members,
			int questPoints,
			int combatLevel,
			boolean boostable,
			Integer difficulty,
			Integer length,
			List<SkillReq> skills,
			List<String> quests)
		{
			this.kind = kind;
			this.displayName = displayName;
			this.members = members;
			this.questPoints = questPoints;
			this.combatLevel = combatLevel;
			this.boostable = boostable;
			this.difficulty = difficulty;
			this.length = length;
			this.skills = Collections.unmodifiableList(new ArrayList<>(skills));
			this.quests = Collections.unmodifiableList(new ArrayList<>(quests));
		}
	}

	static final class SkillReq
	{
		final String skill;
		final int level;

		SkillReq(String skill, int level)
		{
			this.skill = skill;
			this.level = level;
		}
	}
}

package com.agamemnon.companion;

/**
 * Tracks the current slayer task and works out when a genuinely new one has
 * been assigned.
 *
 * Written from the client thread on every varbit change and read from the
 * executor thread that syncs, so everything goes through one dedicated lock.
 */
final class SlayerState
{
	/** The game reports 0 for the task creature when no task is assigned. */
	static final int NO_TASK = 0;

	private final Object lock = new Object();

	private int monsterId;
	private int amountRemaining;
	private int locationId;
	private int slayerPoints;
	private int taskStreak;

	/**
	 * Null until the plugin actually watches a task being handed out. Starting
	 * up mid-task means the original size is simply unknown, and guessing it
	 * from the current count would report a fictional assignment.
	 */
	private Integer amountAssigned;

	/** False until the first reading, which establishes a baseline only. */
	private boolean primed;
	private boolean dirty;

	/**
	 * Records the current values.
	 *
	 * Returns true when this reading is a freshly assigned task, which the
	 * plugin uses to sync promptly rather than waiting for the next tick.
	 *
	 * A kill only ever drives the count down, so a count that goes **up** can
	 * only mean a new assignment — that is what separates two consecutive tasks
	 * for the same monster, which a slayer master will happily hand out.
	 */
	boolean record(int monsterId, int amountRemaining, int locationId, int slayerPoints, int taskStreak)
	{
		synchronized (lock)
		{
			boolean unchanged = primed
				&& monsterId == this.monsterId
				&& amountRemaining == this.amountRemaining
				&& locationId == this.locationId
				&& slayerPoints == this.slayerPoints
				&& taskStreak == this.taskStreak;

			if (unchanged)
			{
				return false;
			}

			boolean newTask = primed
				&& monsterId != NO_TASK
				&& (monsterId != this.monsterId || amountRemaining > this.amountRemaining);

			if (newTask)
			{
				amountAssigned = amountRemaining;
			}
			else if (!primed)
			{
				// First reading of the session. Whatever is on screen was
				// assigned before the plugin was watching.
				amountAssigned = null;
			}

			this.monsterId = monsterId;
			this.amountRemaining = amountRemaining;
			this.locationId = locationId;
			this.slayerPoints = slayerPoints;
			this.taskStreak = taskStreak;
			this.primed = true;
			this.dirty = true;

			return newTask;
		}
	}

	boolean hasPendingChanges()
	{
		synchronized (lock)
		{
			// Nothing to report until a task actually exists.
			return dirty && monsterId != NO_TASK;
		}
	}

	Snapshot snapshot()
	{
		synchronized (lock)
		{
			return new Snapshot(
				monsterId, amountRemaining, locationId,
				slayerPoints, taskStreak, amountAssigned);
		}
	}

	void confirmSent(Snapshot snapshot)
	{
		synchronized (lock)
		{
			// Only clear the flag if nothing moved while the request was in
			// flight; otherwise the newer values still need sending.
			if (snapshot.monsterId == monsterId
				&& snapshot.amountRemaining == amountRemaining
				&& snapshot.locationId == locationId
				&& snapshot.slayerPoints == slayerPoints
				&& snapshot.taskStreak == taskStreak)
			{
				dirty = false;
			}
		}
	}

	void clear()
	{
		synchronized (lock)
		{
			monsterId = 0;
			amountRemaining = 0;
			locationId = 0;
			slayerPoints = 0;
			taskStreak = 0;
			amountAssigned = null;
			primed = false;
			dirty = false;
		}
	}

	static final class Snapshot
	{
		final int monsterId;
		final int amountRemaining;
		final int locationId;
		final int slayerPoints;
		final int taskStreak;
		final Integer amountAssigned;

		private Snapshot(
			int monsterId, int amountRemaining, int locationId,
			int slayerPoints, int taskStreak, Integer amountAssigned)
		{
			this.monsterId = monsterId;
			this.amountRemaining = amountRemaining;
			this.locationId = locationId;
			this.slayerPoints = slayerPoints;
			this.taskStreak = taskStreak;
			this.amountAssigned = amountAssigned;
		}
	}
}

package com.agamemnon.companion;

import com.google.inject.Provides;
import java.io.File;
import java.nio.charset.StandardCharsets;
