import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Agamemnon Companion",
	description = "Sends your own account's XP to your own tracker site",
	tags = {"xp", "tracker", "skilling", "slayer", "farming", "quests", "achievements"}
)
public class AgamemnonCompanionPlugin extends Plugin
{
	/** What the client returns when no account is loaded. Never sent. */
	private static final long NO_ACCOUNT = -1L;

	private static final long BASE_BACKOFF_MILLIS = TimeUnit.SECONDS.toMillis(30);
	private static final long MAX_BACKOFF_MILLIS = TimeUnit.MINUTES.toMillis(30);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AgamemnonCompanionConfig config;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private TrackerClient syncClient;

	@Inject
	private Notifier notifier;

	/**
	 * Quests, diaries and combat achievements barely move, so a change is
	 * absorbed for this long before the block is rebuilt. Without it, one varbit
	 * changing would rebuild eight hundred readings on the client thread.
	 */
	private static final long ACHIEVEMENT_DEBOUNCE_MILLIS = TimeUnit.SECONDS.toMillis(5);

	/** The varbits behind quests and diaries are not all populated at LOGGED_IN. */
	private static final long ACHIEVEMENT_LOGIN_DELAY_MILLIS = TimeUnit.SECONDS.toMillis(3);

	/**
	 * Journal requirement columns land much later than quest varbits. Keep
	 * trying for several minutes; never upload a partial catalog.
	 */
	private static final long[] QUEST_CATALOG_CAPTURE_DELAYS_SECONDS =
		{10, 30, 60, 120, 180, 300};

	private static final long QUEST_CATALOG_POLL_INTERVAL_SECONDS = 30;

	private static final long QUEST_CATALOG_MAX_WAIT_SECONDS = 600;

	private final XpState state = new XpState();
	private final SlayerState slayerState = new SlayerState();
	private final FarmingState farmingState = new FarmingState();
	private final AchievementState achievementState = new AchievementState();
	private final QuestCatalogState questCatalogState = new QuestCatalogState();

	/** Collapses a burst of varbit changes into one rebuild. */
	private final AtomicBoolean achievementRebuildPending = new AtomicBoolean();
	private final AtomicInteger consecutiveFailures = new AtomicInteger();

	/** Names resolved on the client thread, read by the sync thread. */
	private volatile String slayerMonster;
	private volatile String slayerLocation;

	/**
	 * Kept after logout on purpose. The client reports -1 once the account is
	 * unloaded, so a final flush triggered by the logout itself would have
	 * nothing valid to send.
	 */
	private volatile long accountHash = NO_ACCOUNT;

	private volatile String sessionId;
	private volatile String displayName;
	private volatile String accountType;
	private volatile String worldType;
	private volatile boolean artificialWorld;
	private volatile boolean sessionEndPending;
	/** False from logout until the next {@code LOGGED_IN}. */
	private volatile boolean loggedIn;
	private volatile boolean tokenRejected;
	private volatile boolean missingTokenReported;
	private volatile long nextAttemptAtMillis;
	private volatile boolean active;

	private ScheduledFuture<?> syncTask;
	private ScheduledFuture<?> questCatalogPollTask;

	/** Set once a sane catalog has been recorded this login. */
	private volatile boolean questCatalogCaptured;

	@Provides
	AgamemnonCompanionConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AgamemnonCompanionConfig.class);
	}

	@Override
	protected void startUp()
	{
		resetState();
		active = true;

		// Nothing here blocks: invokeLater queues onto the client thread and
		// returns immediately.
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				handleLogin();
			}
		});

		scheduleSyncTask();
	}

	private static final Path QUEST_CAPTURE_DEBUG =
		new File(RuneLite.RUNELITE_DIR, "agamemnon-companion/agamemnon-quest-capture.json").toPath();

	@Override
	protected void shutDown()
	{
		cancelSyncTask();

		// One last flush, to save the minute since the previous sync and to mark
		// the session as over. It runs even with nothing pending: closing the
		// session is the point, and gating this on hasPendingChanges() left a
		// session open forever every time the plugin was toggled off after a
		// successful sync.
		//
		// flush() only enqueues, so this does not block the shutdown.
		if (shouldFlushOnShutdown(active, config.syncEnabled(), accountHash, sessionId))
		{
			sessionEndPending = true;
			flush();
		}

		active = false;
		resetState();
	}

	private void resetState()
	{
		cancelQuestCatalogPoll();
		questCatalogCaptured = false;
		state.clear();
		slayerState.clear();
		farmingState.clear();
		achievementState.clear();
		questCatalogState.clear();
		slayerMonster = null;
		slayerLocation = null;
		accountHash = NO_ACCOUNT;
		sessionId = null;
		displayName = null;
		accountType = null;
		worldType = null;
		artificialWorld = false;
		sessionEndPending = false;
		loggedIn = false;
		tokenRejected = false;
		missingTokenReported = false;
		nextAttemptAtMillis = 0L;
		consecutiveFailures.set(0);
	}

	private void scheduleSyncTask()
	{
		cancelSyncTask();

		int interval = config.syncIntervalSeconds();
		// scheduleWithFixedDelay, not scheduleAtFixedRate: a slow request must
		// not cause runs to pile up behind it.
		syncTask = executor.scheduleWithFixedDelay(
			this::flush, interval, interval, TimeUnit.SECONDS);
	}

	private void cancelSyncTask()
	{
		if (syncTask != null)
		{
			syncTask.cancel(false);
			syncTask = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AgamemnonCompanionConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("syncIntervalSeconds".equals(event.getKey()))
		{
			scheduleSyncTask();
		}
		else if ("apiToken".equals(event.getKey()))
		{
			// A new token deserves a fresh start: clear the rejection latch and
			// any backoff so the next cycle tries immediately.
			tokenRejected = false;
			missingTokenReported = false;
			consecutiveFailures.set(0);
			nextAttemptAtMillis = 0L;
		}
	}

	/**
	 * Runs on the client thread. Records the value and returns — no IO here,
	 * ever.
	 */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		state.record(event.getSkill(), event.getXp());
	}

	/**
	 * Runs on the client thread. Reads the slayer varps and records them; the
	 * actual request rides the normal sync cycle.
	 *
	 * This deliberately does not fire a request per change. The remaining count
	 * ticks down on every kill, so a task of 134 abyssal demons would otherwise
	 * be 134 requests — the kind of volume that gets a plugin rejected for
	 * abuse. A freshly assigned task is the exception: that happens once per
	 * task and is worth sending promptly.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// Quests, diaries and combat achievements are all varbit-backed, and a
		// rebuild reads eight hundred of them, so changes are absorbed for a
		// few seconds rather than acted on one at a time.
		requestAchievementRebuild(ACHIEVEMENT_DEBOUNCE_MILLIS);

		if (!config.slayerEnabled())
		{
			return;
		}

		if (!isSlayerVar(event))
		{
			return;
		}

		int monsterId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int amountRemaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		int locationId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		int points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		int streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);

		boolean newTask = slayerState.record(
			monsterId, amountRemaining, locationId, points, streak);

		// Resolved here because the lookup reads client data and must stay on
		// the client thread.
		slayerMonster = SlayerNames.monster(client, monsterId);
		slayerLocation = SlayerNames.location(client, locationId);

		if (newTask)
		{
			requestFlush();
		}
	}

	private static boolean isSlayerVar(VarbitChanged event)
	{
		int varp = event.getVarpId();
		int varbit = event.getVarbitId();

		return varp == VarPlayerID.SLAYER_TARGET
			|| varp == VarPlayerID.SLAYER_COUNT
			|| varp == VarPlayerID.SLAYER_AREA
			|| varbit == VarbitID.SLAYER_POINTS
			|| varbit == VarbitID.SLAYER_TASKS_COMPLETED;
	}

	/**
	 * Runs on the client thread every tick. Reads whatever farming patches the
	 * player is currently standing among, and records them; the request itself
	 * rides the normal sync cycle.
	 *
	 * Almost every tick this does nothing at all — the player is not in a
	 * farming region, so the lookup misses and it returns. When they are, it is
	 * a handful of varbit reads, and {@link FarmingState} drops everything that
	 * has not changed, so a player standing in a herb patch does not generate a
	 * request a tick.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!config.farmingEnabled() || accountHash == NO_ACCOUNT)
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		WorldPoint location = local.getWorldLocation();
		if (location == null || !patchVarbitsAreTrustworthy())
		{
			return;
		}

		FarmingPatches.Patch[] patches = FarmingPatches.forLocation(
			location.getRegionID(), location.getX(), location.getY(), location.getPlane());

		if (patches.length == 0)
		{
			return;
		}

		long observedAt = System.currentTimeMillis();
		boolean changed = false;

		for (FarmingPatches.Patch patch : patches)
		{
			changed |= farmingState.record(
				patch.id, client.getVarbitValue(patch.varbit), observedAt);
		}

		if (changed)
		{
			// Worth sending promptly: the player has just walked up to a patch,
			// and this is the one moment the game will tell us about it.
			requestFlush();
		}
	}

	/**
	 * Whether the patch varbits currently describe a patch at all.
	 *
	 * Mirrors the guard in RuneLite's own farming tracker: with an interface
	 * loaded, the values these varbits hold are not reliably the patch's. This
	 * is the same class of mistake as reading skill XP before the stats packet
	 * lands — a number that is present but does not mean what it looks like.
	 */
	private boolean patchVarbitsAreTrustworthy()
	{
		for (WidgetNode node : client.getComponentTable())
		{
			if (node.getModalMode() != 1)
			{
				return false;
			}
		}
		return true;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				handleLogin();
				break;

			case LOGIN_SCREEN:
			case CONNECTION_LOST:
				endSession();
				break;

			case HOPPING:
				// Deliberately not an end of session. Hopping is routine, and
				// closing the session on every hop would shatter an evening's
				// play into a dozen fragments.
				requestFlush();
				break;

			default:
				break;
		}
	}

	/** Client thread: {@code GameStateChanged} is dispatched there. */
	private void handleLogin()
	{
		long hash = client.getAccountHash();
		if (hash == NO_ACCOUNT)
		{
			return;
		}

		EnumSet<WorldType> worldTypes = client.getWorldType();
		worldType = AccountDetails.describeWorldTypes(worldTypes);
		artificialWorld = AccountDetails.isArtificialWorld(worldTypes);

		if (hash != accountHash)
		{
			// A different account. The previous account's unsent XP is dropped
			// rather than attributed to this one.
			state.clear();
			farmingState.clear();
			achievementState.clear();
		questCatalogState.clear();
			accountHash = hash;
			displayName = null;
			accountType = null;
			tokenRejected = false;
			beginSession();
		}
		else if (shouldReconnectSession(hash, accountHash, sessionId, loggedIn))
		{
			// Same account, client stayed open. The previous session was closed
			// on logout; reusing its id would append to a dead row and the
			// dashboard would show no current session.
			beginSession();
			state.beginSession();
			requestFlush();
			scheduleQuestCatalogCapture();
		}

		loggedIn = true;

		// The local player, the account-type varbit and the stats are not
		// populated the instant LOGGED_IN fires. Returning false asks the client
		// thread to try again on the next tick.
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				// Dropped out again before anything landed. Stop retrying;
				// the next login schedules a fresh attempt.
				return true;
			}

			Player local = client.getLocalPlayer();
			if (local == null || local.getName() == null)
			{
				return false;
			}

			if (!statsLoaded())
			{
				return false;
			}

			displayName = local.getName();
			accountType = AccountDetails.describeAccountType(
				client.getVarbitValue(VarbitID.IRONMAN));
			primeSkills();
			primeSlayer();

			// Quest and diary varbits lag the login by a couple of seconds, so
			// this waits rather than reading a half-populated block.
			requestAchievementRebuild(ACHIEVEMENT_LOGIN_DELAY_MILLIS);
			scheduleQuestCatalogCapture();
			return true;
		});
	}

	/**
	 * Whether the stats packet has actually arrived.
	 *
	 * The local player appears a tick or two before the skills do, and until
	 * they land {@code getSkillExperience} answers 0 for everything. Sending
	 * that is not merely useless — it is a reading of an account that does not
	 * exist, and it drags the server's baseline down with it.
	 *
	 * Hitpoints is the reliable probe: every account in the game starts at
	 * level 10, which is 1154 XP, so there is no legitimate way for a logged-in
	 * player to sit at zero. Any other skill can honestly be 0.
	 */
	private boolean statsLoaded()
	{
		return client.getSkillExperience(Skill.HITPOINTS) > 0;
	}

	/**
	 * Client thread only. Reads whatever task is already in progress, so
	 * logging in mid-task reports it instead of waiting for the next kill.
	 *
	 * The first reading is a baseline: it records the state without claiming to
	 * know how big the task originally was.
	 */
	private void primeSlayer()
	{
		if (!config.slayerEnabled())
		{
			return;
		}

		int monsterId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int locationId = client.getVarpValue(VarPlayerID.SLAYER_AREA);

		slayerState.record(
			monsterId,
			client.getVarpValue(VarPlayerID.SLAYER_COUNT),
			locationId,
			client.getVarbitValue(VarbitID.SLAYER_POINTS),
			client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED));

		slayerMonster = SlayerNames.monster(client, monsterId);
		slayerLocation = SlayerNames.location(client, locationId);
	}

	/**
	 * Queues a rebuild of the achievement block, collapsing a burst into one.
	 *
	 * The first caller wins the flag and schedules the work; everything that
	 * arrives before it runs is absorbed. That is deliberate — a quest step
	 * moves several varbits in the same tick, and rebuilding once per varbit
	 * would read eight hundred values several times over for one change.
	 */
	private void requestAchievementRebuild(long delayMillis)
	{
		if (!active || !config.achievementsEnabled() || accountHash == NO_ACCOUNT)
		{
			return;
		}

		if (!achievementRebuildPending.compareAndSet(false, true))
		{
			return;
		}

		executor.schedule(() ->
		{
			achievementRebuildPending.set(false);
			clientThread.invokeLater(this::rebuildAchievements);
		}, delayMillis, TimeUnit.MILLISECONDS);
	}

	private void scheduleQuestCatalogCapture()
	{
		if (!active || !config.achievementsEnabled() || accountHash == NO_ACCOUNT)
		{
			return;
		}

		cancelQuestCatalogPoll();
		questCatalogCaptured = false;

		for (long delaySeconds : QUEST_CATALOG_CAPTURE_DELAYS_SECONDS)
		{
			executor.schedule(
				() -> clientThread.invokeLater(this::tryCaptureQuestCatalog),
				delaySeconds,
				TimeUnit.SECONDS);
		}

		questCatalogPollTask = executor.scheduleWithFixedDelay(
			() -> clientThread.invokeLater(this::tryCaptureQuestCatalog),
			QUEST_CATALOG_POLL_INTERVAL_SECONDS,
			QUEST_CATALOG_POLL_INTERVAL_SECONDS,
			TimeUnit.SECONDS);

		executor.schedule(
			this::cancelQuestCatalogPoll,
			QUEST_CATALOG_MAX_WAIT_SECONDS,
			TimeUnit.SECONDS);
	}

	private void cancelQuestCatalogPoll()
	{
		if (questCatalogPollTask != null)
		{
			questCatalogPollTask.cancel(false);
			questCatalogPollTask = null;
		}
	}

	/** Client thread only. Never uploads before {@link QuestRequirements#isCatalogReady}. */
	private void tryCaptureQuestCatalog()
	{
		if (questCatalogCaptured
			|| !active
			|| !config.achievementsEnabled()
			|| accountHash == NO_ACCOUNT)
		{
			return;
		}

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			writeQuestCaptureDebug(false, "not_logged_in", null, null);
			return;
		}

		if (!QuestRequirements.isCatalogReady(client))
		{
			writeQuestCaptureDebug(false, "journal_not_ready", null, null);
			log.debug("quest catalog not ready yet — journal DB still partial");
			return;
		}

		Map<String, QuestRequirements.Entry> catalog = QuestRequirements.readAll(client);
		boolean changed = questCatalogState.record(catalog);
		writeQuestCaptureDebug(
			true,
			changed ? "recorded" : "unchanged",
			catalog.get("COLD_WAR"),
			catalog.get("LUNAR_DIPLOMACY"));
		if (changed)
		{
			log.info("quest catalog captured ({} quests)", catalog.size());
			requestFlush();
		}
		else
		{
			questCatalogCaptured = true;
			cancelQuestCatalogPoll();
		}
	}

	private void maybeCaptureQuestCatalogFromAchievements()
	{
		if (questCatalogCaptured || !QuestRequirements.isCatalogReady(client))
		{
			return;
		}

		Map<String, QuestRequirements.Entry> catalog = QuestRequirements.readAll(client);
		if (questCatalogState.record(catalog))
		{
			log.info("quest catalog captured from achievements rebuild ({} quests)", catalog.size());
			writeQuestCaptureDebug(
				true,
				"achievement_rebuild",
				catalog.get("COLD_WAR"),
				catalog.get("LUNAR_DIPLOMACY"));
			requestFlush();
			questCatalogCaptured = true;
			cancelQuestCatalogPoll();
		}
	}

	private void writeQuestCaptureDebug(
		boolean ready,
		String status,
		QuestRequirements.Entry coldWar,
		QuestRequirements.Entry lunar)
	{
		try
		{
			Files.createDirectories(QUEST_CAPTURE_DEBUG.getParent());
			String lunarRaw = "[]";
			String coldRaw = "[]";
			try
			{
				lunarRaw = QuestRequirements.dumpRequirementColumn(
					client, Quest.LUNAR_DIPLOMACY.getId());
				coldRaw = QuestRequirements.dumpRequirementColumn(
					client, Quest.COLD_WAR.getId());
			}
			catch (RuntimeException e)
			{
				log.debug("could not dump quest requirement columns for debug", e);
			}
			String coldSkills = coldWar == null
				? "[]"
				: QuestRequirements.formatSkillReqs(coldWar.skills);
			String lunarSkills = lunar == null
				? "[]"
				: QuestRequirements.formatSkillReqs(lunar.skills);
			String json = "{"
				+ "\"at\":\"" + Instant.now() + "\","
				+ "\"ready\":" + ready + ","
				+ "\"status\":\"" + status + "\","
				+ "\"lunarRaw\":" + lunarRaw + ","
				+ "\"coldRaw\":" + coldRaw + ","
				+ "\"lunarSkills\":" + lunarSkills + ","
				+ "\"coldWarSkills\":" + coldSkills
				+ "}";
			Files.writeString(
				QUEST_CAPTURE_DEBUG,
				json + '\n',
				StandardCharsets.UTF_8,
				StandardOpenOption.CREATE,
				StandardOpenOption.TRUNCATE_EXISTING);
		}
		catch (Exception e)
		{
			log.debug("could not write quest capture debug file", e);
		}
	}

	/**
	 * Client thread only. Reads quests, diary tiers and combat achievements.
	 *
	 * Quest.getState reads the game's own quest varbits and must run here;
	 * calling it off the client thread is undefined.
	 */
	private void rebuildAchievements()
	{
		if (!config.achievementsEnabled() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Map<String, String> quests = new LinkedHashMap<>();
		for (Quest quest : Quest.values())
		{
			QuestState questState = quest.getState(client);
			quests.put(quest.name(), questState == null ? "UNKNOWN" : questState.name());
		}

		Map<String, Boolean> diaryTiers = new LinkedHashMap<>();
		for (AchievementVarbits.Entry entry : AchievementVarbits.DIARY_TIERS)
		{
			diaryTiers.put(entry.name, client.getVarbitValue(entry.id) > 0);
		}

		Map<String, Boolean> combatTasks = new LinkedHashMap<>();
		for (AchievementVarbits.Entry entry : AchievementVarbits.COMBAT_TASKS)
		{
			combatTasks.put(entry.name, client.getVarbitValue(entry.id) > 0);
		}

		Map<String, Integer> combatTotals = new LinkedHashMap<>();
		for (AchievementVarbits.Entry entry : AchievementVarbits.COMBAT_TOTALS)
		{
			combatTotals.put(entry.name, client.getVarbitValue(entry.id));
		}

		// Raw, undecoded: which bit is which diary task is not recorded in
		// RuneLite, so the values are stored as the game reports them.
		Map<String, Integer> diaryVarps = new LinkedHashMap<>();
		for (AchievementVarbits.Entry entry : AchievementVarbits.DIARY_VARPS)
		{
			diaryVarps.put(entry.name, client.getVarpValue(entry.id));
		}

		// The game keeps its own quest tallies. Counting Quest.values() would
		// disagree with the number in the player's quest list, because the enum
		// mixes miniquests in and the game does not count those.
		Map<String, Integer> questCounts = new LinkedHashMap<>();
		for (AchievementVarbits.Entry entry : AchievementVarbits.QUEST_COUNTS)
		{
			questCounts.put(entry.name, client.getVarbitValue(entry.id));
		}

		int questPoints = client.getVarpValue(VarPlayerID.QP);
		Player local = client.getLocalPlayer();
		int combatLevel = local == null ? 0 : local.getCombatLevel();
		boolean membersWorld = client.getWorldType().contains(WorldType.MEMBERS);

		if (achievementState.record(
			quests, diaryTiers, combatTasks, combatTotals, diaryVarps, questCounts,
			questPoints, combatLevel, membersWorld))
		{
			requestFlush();
		}

		maybeCaptureQuestCatalogFromAchievements();
	}

	/** Client thread only: reads the authoritative XP for every skill. */
	private void primeSkills()
	{
		for (Skill skill : XpState.TRACKED_SKILLS)
		{
			state.record(skill, client.getSkillExperience(skill));
		}

		// Only now is the state worth sending. Callers must have checked
		// statsLoaded() first.
		state.markPrimed();
	}

	private void endSession()
	{
		if (accountHash == NO_ACCOUNT)
		{
			return;
		}

		loggedIn = false;
		sessionEndPending = true;
		requestFlush();
	}

	private void beginSession()
	{
		sessionId = UUID.randomUUID().toString();
		sessionEndPending = false;
		consecutiveFailures.set(0);
		nextAttemptAtMillis = 0L;
	}

	/** Moves the work off the client thread. Never does IO inline. */
	private void requestFlush()
	{
		if (!active)
		{
			return;
		}

		executor.execute(this::flush);
	}

	private void flush()
	{
		if (!active || !config.syncEnabled() || tokenRejected)
		{
			return;
		}

		String token = config.apiToken();
		if (token == null || token.trim().isEmpty())
		{
			reportMissingToken();
			return;
		}

		long hash = accountHash;
		String session = sessionId;
		if (hash == NO_ACCOUNT || session == null)
		{
			return;
		}

		// Leagues, Deadman, beta and tournament worlds hand out XP that is not
		// comparable to the main game.
		if (artificialWorld)
		{
			return;
		}

		if (System.currentTimeMillis() < nextAttemptAtMillis)
		{
			return;
		}

		String trimmed = token.trim();
		flushXp(trimmed, hash, session);
		flushSlayer(trimmed, hash, session);
		flushFarming(trimmed, hash);
		flushAchievements(trimmed, hash);
		flushQuestCatalog(trimmed, hash);
	}

	/** Its own opt-in on top of the master switch, and its own endpoint. */
	private void flushQuestCatalog(String token, long hash)
	{
		if (!config.achievementsEnabled() || !questCatalogState.hasPendingChanges())
		{
			return;
		}

		QuestCatalogState.Snapshot snapshot = questCatalogState.snapshot();
		if (snapshot == null)
		{
			return;
		}

		syncClient.submitQuestCatalog(
			token,
			new QuestCatalogSyncPayload(hash, snapshot, System.currentTimeMillis()),
			outcome -> handleQuestCatalogOutcome(outcome, snapshot));
	}

	private void handleQuestCatalogOutcome(
		SyncOutcome outcome, QuestCatalogState.Snapshot snapshot)
	{
		if (outcome == SyncOutcome.SUCCESS)
		{
			questCatalogState.confirmSent(snapshot);
			questCatalogCaptured = true;
			cancelQuestCatalogPoll();
			noteSuccess();
			return;
		}

		noteFailure(outcome);
	}

	/** Its own opt-in on top of the master switch, and its own endpoint. */
	private void flushAchievements(String token, long hash)
	{
		if (!config.achievementsEnabled() || !achievementState.hasPendingChanges())
		{
			return;
		}

		AchievementState.Snapshot snapshot = achievementState.snapshot();
		if (snapshot == null)
		{
			return;
		}

		syncClient.submitAchievements(
			token,
			new AchievementSyncPayload(hash, snapshot, System.currentTimeMillis()),
			outcome -> handleAchievementOutcome(outcome, snapshot));
	}

	private void handleAchievementOutcome(SyncOutcome outcome, AchievementState.Snapshot snapshot)
	{
		if (outcome == SyncOutcome.SUCCESS)
		{
			achievementState.confirmSent(snapshot);
			noteSuccess();
			return;
		}

		noteFailure(outcome);
	}

	/** Its own opt-in on top of the master switch, and its own endpoint. */
	private void flushFarming(String token, long hash)
	{
		if (!config.farmingEnabled() || !farmingState.hasPendingChanges())
		{
			return;
		}

		List<FarmingState.Observation> snapshot = farmingState.snapshot();
		FarmingSyncPayload payload = new FarmingSyncPayload(
			hash, snapshot, System.currentTimeMillis());

		syncClient.submitFarming(token, payload,
			outcome -> handleFarmingOutcome(outcome, snapshot));
	}

	private void handleFarmingOutcome(
		SyncOutcome outcome, List<FarmingState.Observation> snapshot)
	{
		if (outcome == SyncOutcome.SUCCESS)
		{
			farmingState.confirmSent(snapshot);
			noteSuccess();
			return;
		}

		noteFailure(outcome);
	}

	private void flushXp(String token, long hash, String session)
	{
		// Nothing has been read off the client yet, so there is nothing true to
		// say — not even to close the session. A session that never received a
		// snapshot is closed server-side when the next one opens.
		if (!state.isPrimed())
		{
			return;
		}

		boolean endingSession = sessionEndPending;
		if (!state.hasPendingChanges() && !endingSession)
		{
			return;
		}

		XpState.Snapshot snapshot = state.snapshot();
		XpSyncPayload payload = new XpSyncPayload(
			hash,
			session,
			displayName,
			accountType,
			worldType,
			System.currentTimeMillis(),
			endingSession,
			snapshot.getChangedSkills(),
			snapshot.getTotalXp());

		syncClient.submitXp(token, payload,
			outcome -> handleXpOutcome(outcome, snapshot, endingSession));
	}

	/** Its own opt-in on top of the master switch, and its own endpoint. */
	private void flushSlayer(String token, long hash, String session)
	{
		if (!config.slayerEnabled() || !slayerState.hasPendingChanges())
		{
			return;
		}

		SlayerState.Snapshot snapshot = slayerState.snapshot();
		SlayerSyncPayload payload = new SlayerSyncPayload(
			hash,
			session,
			slayerMonster,
			snapshot.monsterId,
			slayerLocation,
			snapshot.locationId,
			snapshot.amountRemaining,
			snapshot.amountAssigned,
			snapshot.slayerPoints,
			snapshot.taskStreak,
			System.currentTimeMillis());

		syncClient.submitSlayer(token, payload,
			outcome -> handleSlayerOutcome(outcome, snapshot));
	}

	/**
	 * Runs on an OkHttp callback thread.
	 *
	 * Confirming the snapshot only on success is what makes a dropped request
	 * harmless — the unconfirmed XP is simply included again next cycle.
	 */
	private void handleXpOutcome(SyncOutcome outcome, XpState.Snapshot sent, boolean endedSession)
	{
		if (!active)
		{
			return;
		}

		if (outcome == SyncOutcome.SUCCESS)
		{
			state.confirmSent(sent);
			noteSuccess();
			if (endedSession)
			{
				sessionEndPending = false;
			}
			return;
		}

		noteFailure(outcome);
	}

	private void handleSlayerOutcome(SyncOutcome outcome, SlayerState.Snapshot sent)
	{
		if (!active)
		{
			return;
		}

		if (outcome == SyncOutcome.SUCCESS)
		{
			slayerState.confirmSent(sent);
			noteSuccess();
			return;
		}

		noteFailure(outcome);
	}

	private void noteSuccess()
	{
		consecutiveFailures.set(0);
		nextAttemptAtMillis = 0L;
	}

	/** Backoff and the rejection latch are shared: one token, one server. */
	private void noteFailure(SyncOutcome outcome)
	{
		if (outcome == SyncOutcome.AUTH_REJECTED)
		{
			tokenRejected = true;
			log.warn("Agamemnon Companion: the server rejected the API token; syncing is paused "
				+ "until the token is changed.");
			notifier.notify("Agamemnon Companion: your API token was rejected. Check the plugin settings.");
			return;
		}

		nextAttemptAtMillis = System.currentTimeMillis()
			+ backoffMillis(consecutiveFailures.incrementAndGet());
	}

	private void reportMissingToken()
	{
		if (missingTokenReported)
		{
			return;
		}

		missingTokenReported = true;
		log.warn("Agamemnon Companion is enabled but no API token is set; nothing will be sent.");
		notifier.notify("Agamemnon Companion: add your API token in the plugin settings to start syncing.");
	}

	/**
	 * Whether the plugin should send a closing flush as it stops.
	 *
	 * Deliberately does not consider whether any XP is pending. An earlier
	 * version did, and a plugin toggled off after a clean sync had nothing
	 * pending, so no flush went out and the session stayed open forever.
	 */
	static boolean shouldFlushOnShutdown(
		boolean active, boolean syncEnabled, long accountHash, String sessionId)
	{
		return active
			&& syncEnabled
			&& accountHash != NO_ACCOUNT
			&& sessionId != null;
	}

	/**
	 * Whether a {@code LOGGED_IN} for the same account should mint a fresh
	 * session id rather than continue the one closed at logout.
	 */
	static boolean shouldReconnectSession(
		long hash, long accountHash, String sessionId, boolean loggedIn)
	{
		return hash != NO_ACCOUNT
			&& hash == accountHash
			&& sessionId != null
			&& !loggedIn;
	}

	/**
	 * Exponential, capped. A server that is down or a token that is wrong must
	 * not be hammered once a minute forever.
	 */
	static long backoffMillis(int consecutiveFailures)
	{
		if (consecutiveFailures <= 1)
		{
			return BASE_BACKOFF_MILLIS;
		}

		int shift = Math.min(consecutiveFailures - 1, 6);
		return Math.min(MAX_BACKOFF_MILLIS, BASE_BACKOFF_MILLIS << shift);
	}
}

package com.agamemnon.companion;

import javax.annotation.Nullable;

/**
 * The body of a POST to /api/v1/slayer. Field names are the wire contract.
 *
 * Only the local account's own task; nothing here describes another player.
 */
final class SlayerSyncPayload
{
	private final int schemaVersion = XpSyncPayload.SCHEMA_VERSION;

	private final String accountHash;
	private final String sessionId;

	/** Null when the id did not resolve. The server keeps the raw id. */
	private final String monster;
	private final int monsterId;

	private final String location;
	private final Integer locationId;

	private final int amountRemaining;

	/** Null when the plugin did not see the task being assigned. */
	private final Integer amountAssigned;

	private final Integer slayerPoints;
	private final Integer taskStreak;
	private final long clientTimestamp;

	SlayerSyncPayload(
		long accountHash,
		@Nullable String sessionId,
		@Nullable String monster,
		int monsterId,
		@Nullable String location,
		int locationId,
		int amountRemaining,
		@Nullable Integer amountAssigned,
		int slayerPoints,
		int taskStreak,
		long clientTimestamp)
	{
		this.accountHash = Long.toString(accountHash);
		this.sessionId = sessionId;
		this.monster = monster;
		this.monsterId = monsterId;
		this.location = location;
		this.locationId = locationId > 0 ? locationId : null;
		this.amountRemaining = amountRemaining;
		this.amountAssigned = amountAssigned;
		this.slayerPoints = slayerPoints >= 0 ? slayerPoints : null;
		this.taskStreak = taskStreak >= 0 ? taskStreak : null;
		this.clientTimestamp = clientTimestamp;
	}
}

