/**
 * Which farming patches can be read from where the player is standing.
 *
 * The game reuses its patch varbits: 4771 is a coral patch on Great Conch and a
 * hardwood tree at Anglers' Retreat, and which one it currently holds depends
 * on where the player is. Reading a varbit without first establishing that the
 * player is somewhere it means something would record one patch's state against
 * another's name.
 *
 * Generated from RuneLite's own FarmingWorld, and kept in step with the
 * server's table by being generated from the same extraction.
 */
final class FarmingPatches
{
	/** A patch, named the way the API names it. */
	static final class Patch
	{
		final String id;
		final int varbit;

		private Patch(String id, int varbit)
		{
			this.id = id;
			this.varbit = varbit;
		}
	}

	private static final class Area
	{
		/** 0 when the region id alone settles it. */
		final int bounds;
		final Patch[] patches;

		private Area(int bounds, Patch[] patches)
		{
			this.bounds = bounds;
			this.patches = patches;
		}
	}

	private static final Map<Integer, Area[]> BY_REGION = build();

	private FarmingPatches()
	{
	}

	private static Patch p(String id, int varbit)
	{
		return new Patch(id, varbit);
	}

	/**
	 * The patches readable from a position, or empty if there are none.
	 *
	 * Empty is the normal answer: the player is almost never standing in a
	 * farming region.
	 */
	static Patch[] forLocation(int regionId, int x, int y, int plane)
	{
		Area[] areas = BY_REGION.get(regionId);
		if (areas == null)
		{
			return NO_PATCHES;
		}

		int total = 0;
		for (Area area : areas)
		{
			if (inBounds(area.bounds, x, y, plane))
			{
				total += area.patches.length;
			}
		}

		if (total == 0)
		{
			return NO_PATCHES;
		}

		Patch[] result = new Patch[total];
		int at = 0;
		for (Area area : areas)
		{
			if (inBounds(area.bounds, x, y, plane))
			{
				System.arraycopy(area.patches, 0, result, at, area.patches.length);
				at += area.patches.length;
			}
		}
		return result;
	}

	private static final Patch[] NO_PATCHES = new Patch[0];

	/**
	 * The coordinate checks RuneLite uses where a region id is ambiguous.
	 *
	 * Verified exhaustively against RuneLite's own FarmingRegion.isInBounds by
	 * FarmingPatchesTest, over every coordinate of every affected region.
	 */
	static boolean inBounds(int bounds, int x, int y, int plane)
	{
		switch (bounds)
		{
			case 1:
				// Catherby, the seaward side.
				if (x < 2816 || y >= 3456)
				{
					return true;
				}
				return x < 2840 && y >= 3440 && plane == 0;

			case 2:
				// Catherby, the upstairs flower patch.
				return x >= 2840 || y < 3440 || plane == 1;

			case 3:
				// Falador shares a region id with Port Sarim; north of this
				// line is Falador.
				return y >= 3272;

			case 4:
				// Fossil Island, minus a few tiles that belong to the
				// neighbouring hardwood grove.
				if (x == 3753 && y >= 3868 && y <= 3870)
				{
					return false;
				}
				if ((x == 3729 || x == 3728 || x == 3747 || x == 3746)
					&& y <= 3832 && y >= 3830)
				{
					return false;
				}
				return plane == 0;

			case 5:
				// The southern half of the shared Falador/Port Sarim region.
				return y < 3272;

			default:
				return true;
		}
	}

