package com.agamemnon.companion;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;

/**
 * Holds the static quest-requirements catalog and decides whether it is worth
 * sending.
 *
 * Distinct from {@link AchievementState}: that block is the player's progress.
 * This one is Jagex's journal table and barely moves between client updates.
 * Hashing it means a login after an unchanged game build costs one request
 * that the server can skip, rather than rewriting ~40 KB every time.
 */
final class QuestCatalogState
{
	/** Bump when journal parsing changes so clients re-upload stale catalogs. */
	static final int PARSER_REVISION = 3;

	private final Object lock = new Object();

	private Map<String, QuestRequirements.Entry> entries = Collections.emptyMap();
	private String hash;
	private String sentHash;

	boolean record(Map<String, QuestRequirements.Entry> next)
	{
		String computed = computeHash(next);
		synchronized (lock)
		{
			this.entries = Collections.unmodifiableMap(new LinkedHashMap<>(next));
			this.hash = computed;
			return !computed.equals(sentHash);
		}
	}

	boolean hasPendingChanges()
	{
		synchronized (lock)
		{
			return hash != null && !hash.equals(sentHash);
		}
	}

	Snapshot snapshot()
	{
		synchronized (lock)
		{
			if (hash == null)
			{
				return null;
			}
			return new Snapshot(entries, hash);
		}
	}

	void confirmSent(Snapshot snapshot)
	{
		synchronized (lock)
		{
			sentHash = snapshot.hash;
		}
	}

	void clear()
	{
		synchronized (lock)
		{
			entries = Collections.emptyMap();
			hash = null;
			sentHash = null;
		}
	}

	private static String computeHash(Map<String, QuestRequirements.Entry> entries)
	{
		StringBuilder canonical = new StringBuilder("questCatalog{v")
			.append(PARSER_REVISION)
			.append(';');
		for (Map.Entry<String, QuestRequirements.Entry> entry :
			new TreeMap<>(entries).entrySet())
		{
			QuestRequirements.Entry value = entry.getValue();
			canonical.append(entry.getKey()).append('=')
				.append(value.kind).append('/')
				.append(value.displayName).append('/')
				.append(value.members).append('/')
				.append(value.questPoints).append('/')
				.append(value.combatLevel).append('/')
				.append(value.boostable).append('/')
				.append(value.difficulty).append('/')
				.append(value.length).append('/');
			for (QuestRequirements.SkillReq skill : value.skills)
			{
				canonical.append(skill.skill).append(':').append(skill.level).append(',');
			}
			canonical.append('/');
			for (String quest : value.quests)
			{
				canonical.append(quest).append(',');
			}
			canonical.append(';');
		}
		canonical.append('}');

		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] bytes = digest.digest(canonical.toString().getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(bytes.length * 2);
			for (byte b : bytes)
			{
				hex.append(Character.forDigit((b >> 4) & 0xF, 16));
				hex.append(Character.forDigit(b & 0xF, 16));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException("SHA-256 unavailable", e);
		}
	}

	static final class Snapshot
	{
		final Map<String, QuestRequirements.Entry> entries;
		final String hash;

		private Snapshot(Map<String, QuestRequirements.Entry> entries, String hash)
		{
			this.entries = entries;
			this.hash = hash;
		}
	}
}

package com.agamemnon.companion;

/** What came back from a sync attempt. */
enum SyncOutcome
{
	/** The server stored the payload. Only now is the snapshot confirmed. */
	SUCCESS,

	/**
	 * The token is wrong, revoked, or bound to a different account. Retrying
	 * cannot fix it, so syncing pauses until the user changes the setting.
	 */
	AUTH_REJECTED,

	/** Network trouble or a server-side error. Worth retrying, with backoff. */
	TRANSIENT_FAILURE
}

package com.agamemnon.companion;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Sends payloads to the tracker API.
 *
 * The OkHttp client and Gson instance are the ones RuneLite provides, and every
 * call goes out through {@code enqueue} — nothing here blocks, and nothing here
 * runs on the client thread.
 */
@Slf4j
@Singleton
class TrackerClient
{
	/** Named in the config description so the user can see where data goes. */
	static final String SERVICE_HOST = "companion.tpbrothers.com.br";

	private static final String DEFAULT_BASE_URL = "https://" + SERVICE_HOST + "/api/v1";

	/**
	 * Lets a development client point at a local API without exposing an
	 * editable URL field in the config. A free-text URL setting is a generic
	 * exfiltration channel and a strong reason for Plugin Hub rejection.
	 */
	private static final String BASE_URL_PROPERTY = "agamemnon.baseUrl";

	private static final MediaType JSON = MediaType.parse("application/json");

	private final OkHttpClient okHttpClient;
	private final Gson gson;

	@Inject
	TrackerClient(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	static String baseUrl()
	{
		return System.getProperty(BASE_URL_PROPERTY, DEFAULT_BASE_URL);
	}

	void submitXp(String token, XpSyncPayload payload, Consumer<SyncOutcome> onOutcome)
	{
		submit("/sync", token, payload, onOutcome);
	}

	void submitSlayer(String token, SlayerSyncPayload payload, Consumer<SyncOutcome> onOutcome)
	{
		submit("/slayer", token, payload, onOutcome);
	}

	void submitFarming(String token, FarmingSyncPayload payload, Consumer<SyncOutcome> onOutcome)
	{
		submit("/farming", token, payload, onOutcome);
	}

	void submitAchievements(
		String token, AchievementSyncPayload payload, Consumer<SyncOutcome> onOutcome)
	{
		submit("/achievements", token, payload, onOutcome);
	}

	void submitQuestCatalog(
		String token, QuestCatalogSyncPayload payload, Consumer<SyncOutcome> onOutcome)
	{
		submit("/quest-catalog", token, payload, onOutcome);
	}

	private void submit(String path, String token, Object payload, Consumer<SyncOutcome> onOutcome)
	{
		HttpUrl url = HttpUrl.parse(baseUrl() + path);
		if (url == null)
		{
			log.debug("tracker base URL is not a valid HTTP URL");
			onOutcome.accept(SyncOutcome.TRANSIENT_FAILURE);
			return;
		}

		Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				// Debug, not info: this fires on every hiccup and the message
				// can carry the request URL.
				log.debug("tracker request to {} failed", path, e);
				onOutcome.accept(SyncOutcome.TRANSIENT_FAILURE);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				// Closing the Response closes its body, which OkHttp requires
				// even when the body is never read.
				try (Response ignored = response)
				{
					onOutcome.accept(classify(response.code()));
				}
			}
		});
	}

	private static SyncOutcome classify(int code)
	{
		if (code >= 200 && code < 300)
		{
			return SyncOutcome.SUCCESS;
		}

		if (code == 401 || code == 403)
		{
			return SyncOutcome.AUTH_REJECTED;
		}

		log.debug("tracker request rejected with status {}", code);
		return SyncOutcome.TRANSIENT_FAILURE;
	}
}

package com.agamemnon.companion;

import java.util.Map;

/**
 * Body of POST /api/v1/quest-catalog. Field names are the wire contract.
 *
 * Static journal data for every quest the client knows about. Not the player's
 * progress — that stays on /achievements.
 */
final class QuestCatalogSyncPayload
{
	private final int schemaVersion = XpSyncPayload.SCHEMA_VERSION;
	private final String accountHash;
	private final Map<String, QuestRequirements.Entry> quests;
	private final String payloadHash;
	private final long clientTimestamp;

	QuestCatalogSyncPayload(
		long accountHash,
		QuestCatalogState.Snapshot snapshot,
		long clientTimestamp)
	{
		this.accountHash = Long.toString(accountHash);
		this.quests = snapshot.entries;
		this.payloadHash = snapshot.hash;
		this.clientTimestamp = clientTimestamp;
	}
}

package com.agamemnon.companion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The body of a POST to /api/v1/farming. Field names are the wire contract.
 *
 * The raw varbit goes out untouched and the growth maths stays on the server,
 * so a correction to a tick rate does not need a new plugin release and a
 * Plugin Hub review to reach anyone.
 *
 * Only the local account's own patches; nothing here describes another player.
 */
final class FarmingSyncPayload
{
	private final int schemaVersion = XpSyncPayload.SCHEMA_VERSION;

	private final String accountHash;
	private final List<Patch> patches;
	private final long clientTimestamp;

	FarmingSyncPayload(
		long accountHash,
		List<FarmingState.Observation> observations,
		long clientTimestamp)
	{
		this.accountHash = Long.toString(accountHash);
		this.clientTimestamp = clientTimestamp;

		List<Patch> converted = new ArrayList<>(observations.size());
		for (FarmingState.Observation observation : observations)
		{
			converted.add(new Patch(
				observation.patchId, observation.varbitValue, observation.observedAt));
		}
		this.patches = Collections.unmodifiableList(converted);
	}

	private static final class Patch
	{
		private final String patchId;
		private final int varbitValue;

		/** When the player was actually standing there, not when this was sent. */
		private final long observedAt;

		private Patch(String patchId, int varbitValue, long observedAt)
		{
			this.patchId = patchId;
			this.varbitValue = varbitValue;
			this.observedAt = observedAt;
		}
	}
}

package com.agamemnon.companion;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Remembers what each farming patch looked like when it was last seen, and
 * works out what still needs sending.
 *
 * Two threads touch this: {@code record} runs on the client thread from
 * {@code onGameTick}, while {@code snapshot} and {@code confirmSent} run on the
 * executor thread doing the sync. One dedicated lock guards all of it.
 *
 * The dedupe is the whole point. A player standing in a farming region passes
 * through here every game tick, roughly a hundred times a minute, and the patch
 * varbits almost never move. Sending on every tick would be a hundred requests
 * a minute carrying identical data, which is the sort of volume that gets a
 * plugin thrown off the Plugin Hub.
 */
final class FarmingState
{
	/** What the game said about a patch, and when it said it. */
	static final class Observation
	{
		final String patchId;
		final int varbitValue;
		final long observedAt;

		Observation(String patchId, int varbitValue, long observedAt)
		{
			this.patchId = patchId;
			this.varbitValue = varbitValue;
			this.observedAt = observedAt;
		}
	}

	private final Object lock = new Object();

	/** Everything seen this session, by patch id. Insertion ordered for tests. */
	private final Map<String, Observation> current = new LinkedHashMap<>();

	/** The subset not yet acknowledged by the server. */
	private final Map<String, Observation> pending = new LinkedHashMap<>();

	/**
	 * Records a reading.
	 *
	 * Only a change is news. An unchanged patch is not re-sent and its
	 * {@code observedAt} is deliberately left alone: the server extrapolates
	 * from when the state was first seen, and refreshing the timestamp on every
	 * tick would keep resetting that clock and hold the harvest estimate
	 * permanently in the future.
	 *
	 * @return true if this reading was new
	 */
	boolean record(String patchId, int varbitValue, long observedAt)
	{
		synchronized (lock)
		{
			Observation known = current.get(patchId);
			if (known != null && known.varbitValue == varbitValue)
			{
				return false;
			}

			Observation observation = new Observation(patchId, varbitValue, observedAt);
			current.put(patchId, observation);
			pending.put(patchId, observation);
			return true;
		}
	}

	boolean hasPendingChanges()
	{
		synchronized (lock)
		{
			return !pending.isEmpty();
		}
	}

	/**
	 * The observations waiting to go out. The returned list is what
	 * {@link #confirmSent} must be handed back — confirming against a later
	 * read would drop anything seen while the request was in flight.
	 */
	List<Observation> snapshot()
	{
		synchronized (lock)
		{
			return Collections.unmodifiableList(new ArrayList<>(pending.values()));
		}
	}

	/** Called only once the server has acknowledged the snapshot. */
	void confirmSent(List<Observation> sent)
	{
		synchronized (lock)
		{
			for (Observation observation : sent)
			{
				Observation latest = pending.get(observation.patchId);
				// A patch that moved again while the request was on the wire
				// stays pending, carrying the newer value.
				if (latest == observation)
				{
					pending.remove(observation.patchId);
				}
			}
		}
	}

	/** Throws away everything, unsent. Used on logout and on account switch. */
	void clear()
	{
		synchronized (lock)
		{
			current.clear();
			pending.clear();
		}
	}
}
